    #[test]
    fn drive_folds_drank_events_rising_since_the_last_drink() {
        // drive = rise * (t - last_drank_day), clamped [0,1]; last_drank = latest DRANK day.
        let p = SUSTENANCE;
        let home = raddr(1.0);
        let terrain = PlantedTerrain::thermal([]);
        let mut ledger = Ledger::default();
        let mut reg = hornvale_kernel::ConceptRegistry::default();
        reg.register_predicate(DRANK, false, "drank").unwrap();
        reg.register_predicate(RESTED, false, "rested").unwrap();
        reg.register_predicate(SLEPT, false, "slept").unwrap();
        reg.register_predicate(EATEN, false, "eaten").unwrap();
        let e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
        // no drank yet: rises from day 0
        assert!(
            (drive_at(
                &ledger,
                &test_folds(),
                e,
                &home,
                WorldTime::from_std_days(2.0).expect("a day value is finite"),
                &p,
                &terrain,
                ThermalStrategy::Endothermic
            ) - (p.rise * 2.0))
                .abs()
                < 1e-9
        );
        // drank on day 5 -> resets; by day 6 it has risen rise*1
        ledger
            .commit(
                hornvale_kernel::Fact {
                    subject: e,
                    predicate: DRANK.to_string(),
                    object: Value::Flag(true),
                    place: None,
                    day: Some(WorldTime::from_std_days(5.0).expect("finite")),
                    provenance: "t".into(),
                },
                &reg,
            )
            .unwrap();
        assert!(
            (drive_at(
                &ledger,
                &test_folds(),
                e,
                &home,
                WorldTime::from_std_days(6.0).expect("a day value is finite"),
                &p,
                &terrain,
                ThermalStrategy::Endothermic
            ) - (p.rise * 1.0))
                .abs()
                < 1e-9
        );
    }

