    #[test]
    fn rise_at_couples_heat_to_thirst_per_metabolic_class() {
        use ThermalStrategy::*;
        let p = SUSTENANCE;
        let base = p.rise;
        // Endothermic — heat-only (sweating): base at/below thermoneutral,
        // accelerating above.
        assert!((rise_at(THERMONEUTRAL_C, Endothermic, &p) - base).abs() < 1e-12);
        assert!(
            (rise_at(0.0, Endothermic, &p) - base).abs() < 1e-12,
            "cold does not slow an endotherm"
        );
        assert!(
            (rise_at(THERMONEUTRAL_C + HEAT_SCALE_C, Endothermic, &p)
                - base * (1.0 + ENDOTHERM_HEAT_K))
                .abs()
                < 1e-12,
            "one scale above thermoneutral applies the full multiplier"
        );
        // Ectothermic — symmetric (rate tracks ambient, CAP-1), floored.
        assert!(
            rise_at(THERMONEUTRAL_C + HEAT_SCALE_C, Ectothermic, &p)
                > rise_at(THERMONEUTRAL_C, Ectothermic, &p),
            "heat speeds an ectotherm"
        );
        assert!(
            rise_at(-100.0, Ectothermic, &p) < base,
            "deep cold slows an ectotherm below base (torpor)"
        );
        assert!(
            (rise_at(-100.0, Ectothermic, &p) - base * ECTOTHERM_FLOOR).abs() < 1e-12,
            "but never below the floor"
        );
        // Unmodelled flat, in BOTH directions. The heat side alone is what C1
        // mutated, so a cold-side (torpor-shaped) defect on `Unmodelled` —
        // giving it the ectotherm's floored, symmetric response — would have
        // slipped past a heat-only pin. Both sides, or the branch is only half
        // held.
        assert!((rise_at(80.0, Unmodelled, &p) - base).abs() < 1e-12);
        assert!(
            (rise_at(-100.0, Unmodelled, &p) - base).abs() < 1e-12,
            "deep cold does not slow an Unmodelled creature either"
        );
        // An unreadable room (non-finite temperature) couples as neutral.
        assert!((rise_at(f64::INFINITY, Endothermic, &p) - base).abs() < 1e-12);
        // Absent flat, in BOTH directions. `rise_at` never reaches here in
        // production (a construct has no thirst drive) and the arm is kept
        // total; asserting it anyway is what makes this test an instrument for
        // THE GOSSAN, which needs every thermal branch pinned before the type
        // splits. Unmodelled and Absent share this arm today, and that is
        // exactly the grouping `basal_metabolic_rate_w` does NOT use — the
        // disagreement `ThermalStrategy::Unmodelled` exists to express.
        assert!((rise_at(80.0, Absent, &p) - base).abs() < 1e-12);
        assert!((rise_at(-100.0, Absent, &p) - base).abs() < 1e-12);
    }

    #[test]
    fn thirst_integrates_faster_over_a_hot_occupancy() {
        // The path integral (The Kindling): the same elapsed time accrues more
        // thirst in a hot room than a temperate one.
        let p = SUSTENANCE;
        let home = raddr(1.0);
        let hot = PlantedTerrain::thermal([(home.clone(), 45.0)]); // 2× rate (endotherm)
        let temperate = PlantedTerrain::thermal([(home.clone(), 20.0)]); // < thermoneutral → base
        // Read through `sustenance_at` over an EMPTY trail and an empty
        // overlay: no sighting, so the whole span is one segment governed by
        // `home`, which is what the `&[]` sightings argument meant when this
        // test called `integrate_thirst` directly (that function is gone —
        // The Pawl; its body survives verbatim as the oracle in
        // `tests/suite/resident_folds.rs`).
        let empty = crate::resident::Trail::default();
        let e = EntityId::new(1).expect("1 is non-zero");
        let mut witness = crate::resident::ReadWitness::default();
        // A FRESH accumulator per call, because this test deliberately reads
        // the same history through TWO temperature fields and the memo is a
        // function of the temperature field as well as the ledger (see
        // `SustenanceMemo`: the invariant production satisfies is one
        // `LocaleContext` per store, and these two `PlantedTerrain`s are two
        // different fields, not two views of one). Nothing would differ today
        // — an empty trail memoises no window at all — and relying on that
        // would be relying on the fixture rather than on the rule.
        let at = |terrain: &dyn Terrain, witness: &mut crate::resident::ReadWitness| {
            let mut memo = crate::resident::SustenanceMemo::default();
            sustenance_at(
                &empty,
                e,
                &home,
                WorldTime::GENESIS,
                &[],
                td(3.0),
                terrain,
                ThermalStrategy::Endothermic,
                &p,
                &mut memo,
                witness,
            )
        };
        let d_hot = at(&hot, &mut witness);
        let d_temp = at(&temperate, &mut witness);
        assert!(
            d_hot > d_temp,
            "the desert dehydrates faster: {d_hot} vs {d_temp}"
        );
        // A temperate (sub-thermoneutral) room recovers the old flat model.
        assert!((d_temp - p.rise * 3.0).abs() < 1e-9);
        // And the desert is exactly the doubled rate here.
        assert!((d_hot - p.rise * 2.0 * 3.0).abs() < 1e-9);
    }

    #[test]
    fn drive_at_is_deterministic_and_reload_stable() {
        // Fold determinism: same ledger + t -> same value; and serialize->reload of
        // the ledger yields the identical drive (the DRIVE == FOLD contract).
        let p = SUSTENANCE;
        let home = raddr(1.0);
        let terrain = PlantedTerrain::thermal([]);
        let mut ledger = Ledger::default();
        let mut reg = hornvale_kernel::ConceptRegistry::default();
        reg.register_predicate(DRANK, false, "drank").unwrap();
        reg.register_predicate(RESTED, false, "rested").unwrap();
        reg.register_predicate(SLEPT, false, "slept").unwrap();
        reg.register_predicate(EATEN, false, "eaten").unwrap();
        let e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
        for day in [1.0, 4.0, 9.0] {
            ledger
                .commit(
                    hornvale_kernel::Fact {
                        subject: e,
                        predicate: DRANK.to_string(),
                        object: Value::Flag(true),
                        place: None,
                        day: Some(
                            WorldTime::from_std_days(day).expect("test fixture day is finite"),
                        ),
                        provenance: "t".into(),
                    },
                    &reg,
                )
                .unwrap();
        }
        let t = WorldTime::from_std_days(12.3).expect("a day value is finite");
        let a = drive_at(
            &ledger,
            &test_folds(),
            e,
            &home,
            t,
            &p,
            &terrain,
            ThermalStrategy::Endothermic,
        );
        let b = drive_at(
            &ledger,
            &test_folds(),
            e,
            &home,
            t,
            &p,
            &terrain,
            ThermalStrategy::Endothermic,
        );
        assert_eq!(a, b);
        let json = serde_json::to_string(&ledger).unwrap();
        let reloaded: Ledger = serde_json::from_str(&json).unwrap();
        assert_eq!(
            drive_at(
                &reloaded,
                &test_folds(),
                e,
                &home,
                t,
                &p,
                &terrain,
                ThermalStrategy::Endothermic
            ),
            a,
            "drive re-derives identically after reload"
        );
    }

    fn addr(seed: f64) -> Facet {
        Facet::containing([seed, 0.0, 0.0], 6)
    }

    #[test]
    fn decide_plans_to_water_when_thirsty_and_home_when_not() {
        let p = SUSTENANCE;
        let home = addr(1.0);
        let water = home.neighbors()[0].clone();
        // parched (drive >= act), at home, KNOWS water -> the plan's first
        // step, toward water
        let v = Perceived {
            position: home.clone(),
            drive: 0.9,
            fatigue: 0.0,
            believed_water: Some(water.clone()),
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: None,
        };
        assert_eq!(
            decide(&v, &home, &p, 10_000),
            Intent::Do(Action::MoveTo(water.clone()))
        );
        // not thirsty, away from home (at water) -> the plan's first step home
        let v = Perceived {
            position: water.clone(),
            drive: 0.1,
            fatigue: 0.0,
            believed_water: Some(water.clone()),
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: None,
        };
        assert_eq!(
            decide(&v, &home, &p, 10_000),
            Intent::Do(Action::MoveTo(home.clone()))
        );
        // not thirsty, at home -> nothing to do
        let v = Perceived {
            position: home.clone(),
            drive: 0.1,
            fatigue: 0.0,
            believed_water: Some(water.clone()),
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: None,
        };
        assert_eq!(decide(&v, &home, &p, 10_000), Intent::Hold);
    }

    #[test]
    fn decide_holds_when_the_plan_is_unreachable_within_budget() {
        // A zero search budget can never find even a one-step plan: both the
        // thirsty-and-knows-water (plan-to-water) and homeward (plan-to-room)
        // branches must give up rather than loop.
        let p = SUSTENANCE;
        let home = addr(1.0);
        let water = home.neighbors()[0].clone();
        let thirsty = Perceived {
            position: home.clone(),
            drive: 0.9,
            fatigue: 0.0,
            believed_water: Some(water.clone()),
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: None,
        };
        assert_eq!(decide(&thirsty, &home, &p, 0), Intent::Hold);
        let away_not_thirsty = Perceived {
            position: water.clone(),
            drive: 0.1,
            fatigue: 0.0,
            believed_water: Some(water.clone()),
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: None,
        };
        assert_eq!(decide(&away_not_thirsty, &home, &p, 0), Intent::Hold);
    }

    pub(super) fn raddr(seed: f64) -> Facet {
        Facet::containing([seed, 0.0, 0.0], 6)
    }

    #[test]
    fn decide_plans_to_believed_water_or_explores_when_ignorant() {
        // BELIEF DRIVES THE DECISION: two views identical but for belief produce
        // different first moves — the believer A*-steps toward its known water; the
        // ignorant one takes the explore step. (Water two hops away so the A* first
        // step differs from an arbitrary explore step.)
        let p = SUSTENANCE;
        let home = raddr(1.0);
        let mid = home.neighbors()[0].clone();
        let water = mid
            .neighbors()
            .iter()
            .find(|n| **n != home)
            .unwrap()
            .clone();
        let explore = home.neighbors()[2].clone(); // a different direction
        // believer, thirsty, at home -> first A* step toward water (== mid)
        let believer = Perceived {
            position: home.clone(),
            drive: 0.9,
            fatigue: 0.0,
            believed_water: Some(water.clone()),
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: Some(explore.clone()),
        };
        assert_eq!(
            decide(&believer, &home, &p, 10_000),
            Intent::Do(Action::MoveTo(mid.clone()))
        );
        // ignorant, thirsty, at home -> the explore step (not toward water)
        let ignorant = Perceived {
            position: home.clone(),
            drive: 0.9,
            fatigue: 0.0,
            believed_water: None,
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: Some(explore.clone()),
        };
        assert_eq!(
            decide(&ignorant, &home, &p, 10_000),
            Intent::Do(Action::MoveTo(explore.clone()))
        );
        assert_ne!(
            mid, explore,
            "the two beliefs must yield different moves for this to prove anything"
        );
        // ignorant with nowhere new to explore -> Hold
        let stuck = Perceived {
            position: home.clone(),
            drive: 0.9,
            fatigue: 0.0,
            believed_water: None,
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: None,
        };
        assert_eq!(decide(&stuck, &home, &p, 10_000), Intent::Hold);
        // not thirsty, away from home -> plan home (unchanged behavior)
        let sated_away = Perceived {
            position: water.clone(),
            drive: 0.1,
            fatigue: 0.0,
            believed_water: Some(water.clone()),
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: None,
        };
        assert!(matches!(
            decide(&sated_away, &home, &p, 10_000),
            Intent::Do(Action::MoveTo(_))
        ));
    }

    #[test]
    fn a_thirsty_agent_plans_to_water_and_the_tick_walks_it() {
        // Over a wait long enough to grow thirsty, the tick commits a run of agent-at
        // moves ending at water plus a `drank`, and the drive resets. Under the
        // belief model the agent starts IGNORANT: its first approach to water
        // is an EXPLORE step (not a ground-truth beeline) — water is planted
        // as home's only low neighbour, so exploration discovers it on the
        // very first thirsty step; belief then persists (the fold across the
        // walk) so every later cycle A*-steps to it directly.
        let mut world_reg = hornvale_kernel::ConceptRegistry::default();
        world_reg
            .register_predicate(AGENT_AT, false, "pos")
            .unwrap();
        world_reg.register_predicate(DRANK, false, "drank").unwrap();
        world_reg
            .register_predicate(RESTED, false, "rested")
            .unwrap();
        world_reg.register_predicate(SLEPT, false, "slept").unwrap();
        world_reg.register_predicate(EATEN, false, "eaten").unwrap();
        for (key, doc) in errand_predicates() {
            world_reg.register_predicate(key, false, doc).unwrap();
        }
        let mut ledger = Ledger::default();
        let e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
        let home = raddr(1.0);
        let water = home.neighbors()[0].clone();
        let npc = Body {
            entity: e,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home: home.clone(),
            resource: water.clone(),
            species: "goblin".into(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Endothermic,
            niche: default_diet_niche(),
            boldness: 0.5,
            threat_niche: mortal_threat_niche(),
            // The action clock's reference mass (The Action Clock T2): tempo is
            // exactly `1.0` here, so this fixture's timings are unmoved.
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: "herder".into(),
        };
        // Elevation still steers the exploration prior (downhill), separate
        // from fresh-water truth: `water` must be the uniquely lowest
        // neighbor for the comment above's "very first thirsty step"
        // guarantee to hold deterministically (not by Facet tie-break
        // luck among equally-INFINITY neighbors).
        let t = PlantedTerrain {
            elevations: [(water.clone(), 0.0)].into_iter().collect(),
            fresh: [water.clone()].into_iter().collect(),
            ..Default::default()
        };
        let folds = test_folds();
        let sys = DriveMovements {
            npcs: vec![npc.clone()],
            from: WorldTime::GENESIS,
            to: WorldTime::from_std_days(40.0).expect("a day value is finite"),
            params: SUSTENANCE,
            // No sky in a planted-terrain fixture: the action clock takes its
            // base rate (spec §4.1).
            day_ticks: None,
            terrain: &t,
            folds: &folds,
        };
        let next =
            hornvale_kernel::tick(&ledger, &[&sys], &["drive-movements"], &world_reg).unwrap();
        // At least one drank committed (the agent reached water and drank).
        let drank_count = next.find(DRANK).filter(|f| f.subject == e).count();
        assert!(drank_count >= 1, "the agent drank");
        // agent-at moves committed (the journey), and bounded (not one per
        // tick / not exploding — THE NO-THRASH GUARD, the campaign's
        // characteristic risk): a ~5.7-day rise cycle over 40 days is ~7
        // cycles, each a small, fixed number of moves.
        let moves = next.find(AGENT_AT).filter(|f| f.subject == e).count();
        assert!(moves >= 1, "the agent walked");
        assert!(
            moves <= 60,
            "expected a bounded number of moves, not one per tick or an explosion; got {moves}"
        );
        let _ = ledger;
    }

    /// The Hand, Task 5 fix round 1's mutation proof: the SAME thirsty body,
    /// on the SAME walk, differing only in which [`Controller`]
    /// [`DriveMovements::step_one_with_controller`] is asked. This is the
    /// deterministic, seed-independent proof that the trait actually gates
    /// what gets committed — the fixture is
    /// `a_thirsty_agent_plans_to_water_and_the_tick_walks_it`'s own (a body
    /// guaranteed to want water within the window), read twice.
    ///
    /// `DefaultController` must be a byte-identical PASS-THROUGH of
    /// `decide_step`'s own resolution: the body drinks, exactly as it would
    /// with no controller in the loop at all — this is what proves every
    /// existing NPC's committed trail is unperturbed by this task.
    /// `PlayerController` must HOLD it — returning no action — regardless of
    /// what the body's own arbitration wants. Scope this claim carefully: at
    /// THIS unit's level the `Hold` is what leaves the returned fact vector
    /// empty; before The Minute the live session discarded the driven walk's
    /// facts unconditionally (`Session::wait`), so there the DISCARD and not
    /// the `Hold` kept the ledger clean — since The Minute `Session::wait`
    /// commits whatever the walk returns, so a `Hold`ing `PlayerController`
    /// keeping the ledger clean now depends on the SAME emptiness this unit
    /// pins, at both levels. Spec §5.2's "commits on `Do`, nothing on
    /// `Hold`" wording described the session level and was withdrawn for it
    /// (The Hand, Task 5); do not re-import it here. Swap
    /// `DefaultController` for `PlayerController` in the first call (or vice
    /// versa) and one of the two assertions below reddens; that swap is
    /// exactly what a session-level test cannot always force (seed 42's own
    /// possessed bodies, walked solo, happen to arbitrate straight to `Hold`
    /// on their very first decision — see the Task 5 fix-round report), which
    /// is why this test constructs a body it KNOWS wants to act.
    #[test]
    fn a_default_controller_passes_through_and_a_player_controller_holds() {
        let mut ledger = Ledger::default();
        let e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
        let home = raddr(1.0);
        let water = home.neighbors()[0].clone();
        let npc = Body {
            entity: e,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home: home.clone(),
            resource: water.clone(),
            species: "goblin".into(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Endothermic,
            niche: default_diet_niche(),
            boldness: 0.5,
            threat_niche: mortal_threat_niche(),
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: "herder".into(),
        };
        let t = PlantedTerrain {
            elevations: [(water.clone(), 0.0)].into_iter().collect(),
            fresh: [water.clone()].into_iter().collect(),
            ..Default::default()
        };
        let folds = test_folds();
        let sys = DriveMovements {
            npcs: vec![npc.clone()],
            from: WorldTime::GENESIS,
            to: WorldTime::from_std_days(40.0).expect("a day value is finite"),
            params: SUSTENANCE,
            day_ticks: None,
            terrain: &t,
            folds: &folds,
        };

        let (default_facts, _written) = sys.step_one_with_controller(
            &ledger,
            &npc,
            &mut RoomMeshMemo::new(),
            &mut HomeNavCache::new(),
            &mut RouteMemo::new(),
            &mut DefaultController,
        );
        assert!(
            default_facts.iter().any(|f| f.predicate == DRANK),
            "DefaultController is a pass-through of the body's own arbitration \
             (which wants water) — it must act: {default_facts:?}"
        );

        let (player_facts, _written) = sys.step_one_with_controller(
            &ledger,
            &npc,
            &mut RoomMeshMemo::new(),
            &mut HomeNavCache::new(),
            &mut RouteMemo::new(),
            &mut crate::controller::PlayerController::new(),
        );
        assert!(
            player_facts.is_empty(),
            "PlayerController holds the body regardless of what its own \
             arbitration wants, and commits nothing: {player_facts:?}"
        );
    }

    /// The Coercion, spec §7 H3 — "the act trail is indistinguishable": a
    /// body driven by [`crate::controller::ImposedController`] and the same
    /// body driven by [`DefaultController`], same seed, same tick span,
    /// commit facts differing only in *which* acts were chosen, never in
    /// their shape, cost, or subject.
    ///
    /// **Chosen instrument, and why.** `step_one_with_controller` is
    /// `pub(crate)`, so — like H2 — this cannot live in the integration
    /// suite; it lives here, beside
    /// `a_default_controller_passes_through_and_a_player_controller_holds`,
    /// whose exact shape (one fixture, two controllers, compare the
    /// returned facts) this test follows. The fixture is `charged_walk_fixture`
    /// (below), not a fresh minimal one: over its 39-day span it is already
    /// proven (by `drinking_and_eating_now_cost_time`) to emit `drank`,
    /// `eaten`, AND `rested` alongside `agent-at` — the richest walk this
    /// file has, so a comparison over it exercises every predicate shape
    /// `DriveMovements` can commit, not only the one thirst allows.
    ///
    /// **The prediction is stronger than the spec's own wording asks for,
    /// deliberately.** `ImposedController::intend` (`controller.rs`) is an
    /// unconditional, stateless delegation to `DefaultController::intend`,
    /// which is itself a pure pass-through of `resolution.intent` — so
    /// nothing about which controller is live can change what either one
    /// answers at any decision point of an identical walk. The two
    /// committed `Vec<Fact>` are therefore predicted to be BYTE-IDENTICAL
    /// (`Fact` derives `PartialEq`), not merely same-shaped, and the same
    /// last-decision mode/affect/suppressed-ranks triple this walk returns
    /// is predicted identical too.
    ///
    /// **Coordinator review (post-Task-5): this result is DEDUCIBLE from
    /// `controller.rs:162-166` before the fixture ever runs, not evidence
    /// this fixture gathered** — today's `ImposedController` is a provable
    /// no-op relative to `DefaultController`, so this assertion holds
    /// trivially and must be re-measured once `ImposedController` gains
    /// real intent (see H4's own doc comment, right below, for the fuller
    /// statement of this and a pointer to the comparison that IS live
    /// today: `PlayerController` vs `ImposedController`, free versus HELD,
    /// which Task 4 already measured and found DIVERGES in felt state
    /// while committing identical facts).
    #[test]
    fn h3_the_act_trail_under_an_imposed_controller_is_byte_identical_to_the_default_controller() {
        let (ledger, terrain, npc) = charged_walk_fixture();
        let folds = test_folds();
        let sys = DriveMovements {
            npcs: vec![npc.clone()],
            from: WorldTime::from_std_days(1.0).expect("a day value is finite"),
            to: WorldTime::from_std_days(40.0).expect("a day value is finite"),
            params: SUSTENANCE,
            day_ticks: None,
            terrain: &terrain,
            folds: &folds,
        };

        let (default_facts, default_written) = sys.step_one_with_controller(
            &ledger,
            &npc,
            &mut RoomMeshMemo::new(),
            &mut HomeNavCache::new(),
            &mut RouteMemo::new(),
            &mut DefaultController,
        );
        let (imposed_facts, imposed_written) = sys.step_one_with_controller(
            &ledger,
            &npc,
            &mut RoomMeshMemo::new(),
            &mut HomeNavCache::new(),
            &mut RouteMemo::new(),
            &mut crate::controller::ImposedController::new(),
        );

        assert!(
            !default_facts.is_empty(),
            "the fixture must actually walk and commit something, or this \
             proves nothing: {default_facts:?}"
        );
        assert_eq!(
            default_facts, imposed_facts,
            "H3: an imposed controller's committed trail must be BYTE-IDENTICAL \
             to the default controller's — ImposedController::intend is a pure, \
             stateless delegation to DefaultController::intend, and nothing else \
             in the walk reads which controller is live"
        );
        assert_eq!(
            default_written.felt.mode, imposed_written.felt.mode,
            "H3: the same last commitment mode either way"
        );
        assert_eq!(
            default_written.felt.affect, imposed_written.felt.affect,
            "H3: the same last resolution's felt state either way"
        );
        assert_eq!(
            default_written.felt.suppressed, imposed_written.felt.suppressed,
            "H3: the same discarded drive ranks either way"
        );
        assert_eq!(
            default_written.position, imposed_written.position,
            "H3: the same room at the end of the walk either way"
        );
    }

    /// The Coercion, spec §7 H4 — "the null this campaign is prepared to
    /// report": count the distinct FACT SHAPES emitted under imposition
    /// versus free running, over a stated denominator. A fact SHAPE here is
    /// its PREDICATE identity — this file's own closed roster of everything
    /// `DriveMovements` can ever commit is exactly four constants
    /// ([`AGENT_AT`], [`DRANK`], [`RESTED`], [`EATEN`], grep-verified: the
    /// only `pub const _: &str` predicate names this file defines), so the
    /// stated denominator is **4**.
    ///
    /// **Coordinator review correction (post-Task-5, prose-only — no
    /// assertion in this test changed): this equality is DEDUCIBLE, not
    /// measured, and this is the same finding H3's doc comment now states
    /// too.** `ImposedController::intend` (`controller.rs:162-166`) is
    /// `self.inner.intend(body, resolution)` with `inner: DefaultController`
    /// — a stateless pass-through taking no fixture-dependent branch at
    /// all. That means the SET-equality this test measures follows from
    /// `controller.rs`'s own text before either fixture below ever runs: no
    /// trajectory choice, however varied, could have produced a different
    /// outcome. **Today's stub `ImposedController` is provably a no-op
    /// relative to `DefaultController`, so H3 and H4 both hold trivially,
    /// and must be RE-MEASURED once `ImposedController` gains real intent**
    /// (a possessing creature's own arbitration — spec §5's deferred future
    /// work) — at that point the delegation this deduction rests on no
    /// longer holds, and the two hypotheses become live measurements again
    /// rather than restatements of `controller.rs`'s own source.
    ///
    /// **What this test still buys, framed correctly: a regression guard,
    /// not a discovery.** It reddens the moment `ImposedController` grows
    /// any logic that diverges from `DefaultController` — exactly this
    /// campaign's own stated trajectory — so it is worth keeping as a
    /// tripwire for that day, not as evidence about possession's
    /// consequences today.
    ///
    /// **The comparison that IS live today, and is NOT this one:**
    /// `PlayerController` vs `ImposedController` — free versus HELD, the
    /// pair the game actually runs at `Session::wait`'s one real call site
    /// — which Task 4 already measured directly
    /// (`session::tests::driven_felt_state_can_move_under_an_imposed_controller_during_wait`)
    /// and found produces IDENTICAL committed facts but DIVERGENT felt
    /// state (`driven_mode`/`driven_affect`: `Pursuing(Fatigue)`/`Eager`
    /// free vs `Idle`/`Content` held, seed 42). A reader who wants the
    /// interesting result belongs there, not here — H3/H4 answer a
    /// preregistered question about two controllers that happen, today, to
    /// be the same controller in disguise.
    ///
    /// Instrument (unchanged from the original run — this correction is
    /// prose-only): same call as H3 (`step_one_with_controller`, in-module
    /// for the same `pub(crate)` reason H3 gives), reduced to the SET of
    /// predicate names each run touched, pooled over TWO fixtures:
    /// `charged_walk_fixture` (drink + eat + rest) and a second,
    /// differently-planted single-drive fixture (the body
    /// `a_default_controller_passes_through_and_a_player_controller_holds`
    /// uses — a different species/terrain/genesis-vs-day-1 start). **The
    /// two fixtures corroborate nothing beyond the deduction above** — they
    /// are two instances of a comparison whose outcome the delegation
    /// already fixed, not two independent trials that could have
    /// disagreed.
    ///
    /// **A prediction this test made and got wrong, worth stating rather
    /// than quietly dropping — and independent of the deduction above.**
    /// The second fixture was chosen expecting a NARROWER reachable set
    /// than the first (thirst-only, on the theory that a body minted fresh
    /// with no prior `eaten`/`rested` history and a one-hop water source
    /// would satisfy thirst long before hunger or fatigue crossed their own
    /// thresholds in a 39-day window). Measured directly: it is not
    /// narrower — over 39 days this fixture ALSO emits `eaten` and
    /// `rested`, the same full four-predicate set the first fixture does.
    /// That is a real fact about how generous a 39-day window is against
    /// this file's own drive-cycle constants (`SUSTENANCE.act/
    /// SUSTENANCE.rise ≈ 5.7` days), not a defect in the test — and it is
    /// the one thing about this test's own setup that genuinely needed
    /// running to find out, even though the imposed/free equality itself
    /// did not.
    #[test]
    fn h4_the_distinct_fact_shapes_imposed_and_free_can_reach_are_identical() {
        let known_predicates: std::collections::BTreeSet<String> =
            [AGENT_AT, DRANK, RESTED, SLEPT, EATEN]
                .into_iter()
                .chain(errand_predicates().iter().map(|(key, _)| *key))
                .map(str::to_string)
                .collect();
        assert_eq!(
            known_predicates.len(),
            13,
            "the stated denominator: DriveMovements's own closed predicate \
             roster (AGENT_AT/DRANK/RESTED/SLEPT/EATEN, plus the eight \
             `errand/*` predicates The Warrant Task 2 added at every MoveTo's \
             errand boundary). It was FOUR until The Wicket's Task 8 split the \
             one recovery act into a conscious rest and an unconscious sleep, \
             which needed two predicates because the fold repays them at \
             different rates; it was five until The Warrant."
        );

        fn shapes_of(facts: &[Fact]) -> std::collections::BTreeSet<String> {
            facts.iter().map(|f| f.predicate.clone()).collect()
        }

        // Fixture A: `charged_walk_fixture` — drink, eat, AND rest are all
        // reachable in its 39-day span (pinned by
        // `drinking_and_eating_now_cost_time`, which asserts all three
        // predicates appear on this exact fixture).
        let (ledger_a, terrain_a, npc_a) = charged_walk_fixture();
        let folds = test_folds();
        let sys_a = DriveMovements {
            npcs: vec![npc_a.clone()],
            from: WorldTime::from_std_days(1.0).expect("a day value is finite"),
            to: WorldTime::from_std_days(40.0).expect("a day value is finite"),
            params: SUSTENANCE,
            day_ticks: None,
            terrain: &terrain_a,
            folds: &folds,
        };
        let (default_facts_a, ..) = sys_a.step_one_with_controller(
            &ledger_a,
            &npc_a,
            &mut RoomMeshMemo::new(),
            &mut HomeNavCache::new(),
            &mut RouteMemo::new(),
            &mut DefaultController,
        );
        let (imposed_facts_a, ..) = sys_a.step_one_with_controller(
            &ledger_a,
            &npc_a,
            &mut RoomMeshMemo::new(),
            &mut HomeNavCache::new(),
            &mut RouteMemo::new(),
            &mut crate::controller::ImposedController::new(),
        );

        // Fixture B: the single-drive thirst fixture
        // `a_default_controller_passes_through_and_a_player_controller_holds`
        // uses — a different species, terrain, and starting history than
        // fixture A (see this test's own doc comment for the measured
        // finding that its reachable set is NOT narrower in practice, over
        // this 39-day window).
        let mut ledger_b = Ledger::default();
        let e_b = ledger_b.mint_entity(test_lineage(ledger_b.entity_count() as u16));
        let home_b = raddr(1.0);
        let water_b = home_b.neighbors()[0].clone();
        let npc_b = Body {
            entity: e_b,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home: home_b.clone(),
            resource: water_b.clone(),
            species: "goblin".into(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Endothermic,
            niche: default_diet_niche(),
            boldness: 0.5,
            threat_niche: mortal_threat_niche(),
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: "herder".into(),
        };
        let t_b = PlantedTerrain {
            elevations: [(water_b.clone(), 0.0)].into_iter().collect(),
            fresh: [water_b.clone()].into_iter().collect(),
            ..Default::default()
        };
        let folds = test_folds();
        let sys_b = DriveMovements {
            npcs: vec![npc_b.clone()],
            from: WorldTime::GENESIS,
            to: WorldTime::from_std_days(40.0).expect("a day value is finite"),
            params: SUSTENANCE,
            day_ticks: None,
            terrain: &t_b,
            folds: &folds,
        };
        let (default_facts_b, ..) = sys_b.step_one_with_controller(
            &ledger_b,
            &npc_b,
            &mut RoomMeshMemo::new(),
            &mut HomeNavCache::new(),
            &mut RouteMemo::new(),
            &mut DefaultController,
        );
        let (imposed_facts_b, ..) = sys_b.step_one_with_controller(
            &ledger_b,
            &npc_b,
            &mut RoomMeshMemo::new(),
            &mut HomeNavCache::new(),
            &mut RouteMemo::new(),
            &mut crate::controller::ImposedController::new(),
        );

        let mut free_shapes = shapes_of(&default_facts_a);
        free_shapes.extend(shapes_of(&default_facts_b));
        let mut imposed_shapes = shapes_of(&imposed_facts_a);
        imposed_shapes.extend(shapes_of(&imposed_facts_b));

        assert!(
            !free_shapes.is_empty(),
            "the pooled fixtures must actually commit something, or this \
             proves nothing"
        );
        assert!(
            free_shapes.is_subset(&known_predicates),
            "every emitted predicate must be one of the {} this file can \
             ever commit: got {free_shapes:?}",
            known_predicates.len()
        );
        assert_eq!(
            imposed_shapes,
            free_shapes,
            "H4: the set of distinct fact shapes (predicates) an imposed run \
             can reach and the set a free run can reach, pooled over {} \
             predicates' worth of denominator and 2 fixtures, are IDENTICAL \
             — but that equality is DEDUCIBLE from \
             `ImposedController::intend`'s pass-through delegation \
             (controller.rs:162-166) before either fixture runs, NOT \
             established by running them. Today's stub is provably a no-op \
             relative to `DefaultController`, so this assertion is a \
             regression tripwire for the day it gains real intent, not \
             evidence that possession is invisible in reachable consequence",
            known_predicates.len()
        );
    }

    /// The Hand, Task 5 fix round 3, N2: `step_one_with_controller`'s own
    /// `catch_up` call used to reborrow the LIVE controller, so the moment a
    /// verb ever queued a real action (`PlayerController::queue`, still
    /// dormant in production — spec §1), catch-up would run first, TAKE that
    /// queued action for itself, discard it (`Intent::Do(_) => break
    /// 'catchup` — a committing action catch-up refuses to fabricate), and
    /// `advance_one` would then see nothing pending and Hold. The player's
    /// own action would vanish before the tick meant to enact it ever ran.
    ///
    /// This constructs exactly that hazard: an entity with an EARLIER
    /// committed `agent-at` (day 0) than the walk's own `from` (day 3), which
    /// is what gives `catch_up` a real 3-day gap to iterate at all — a
    /// same-day fixture (like the two tests above) never enters catch-up's
    /// loop and would pass even under the bug. A real action (`Drink`, which
    /// `advance_one` commits unconditionally regardless of position) is
    /// queued into the controller BEFORE the call. If it survives to be
    /// committed, catch-up never touched it.
    #[test]
    fn catch_up_does_not_consume_the_controllers_pending_action() {
        let mut registry = ConceptRegistry::default();
        registry.register_predicate(AGENT_AT, false, "pos").unwrap();
        registry.register_predicate(DRANK, false, "drank").unwrap();
        let mut ledger = Ledger::default();
        let e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
        let home = raddr(1.0);
        // The gap catch_up will reconstruct: last seen here on day 0, and the
        // walk itself does not open until day 3.
        ledger
            .commit(agent_at_fact(e, &home, td(0.0), "test setup"), &registry)
            .unwrap();
        let npc = Body {
            entity: e,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home: home.clone(),
            resource: home.clone(),
            species: "goblin".into(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Endothermic,
            niche: default_diet_niche(),
            boldness: 0.5,
            threat_niche: mortal_threat_niche(),
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: "herder".into(),
        };
        let t = PlantedTerrain::default();
        let folds = test_folds();
        let sys = DriveMovements {
            npcs: vec![npc.clone()],
            from: WorldTime::from_std_days(3.0).expect("a day value is finite"),
            // Slack beyond `from`: `Drink`'s own clock charge (`cost_ticks`)
            // must land at or before `to`, or `advance_one`'s interval guard
            // returns before ever reaching the commit match — a half-day is
            // generous next to `Drink`'s 150-tick base cost.
            to: WorldTime::from_std_days(3.5).expect("a day value is finite"),
            params: SUSTENANCE,
            day_ticks: None,
            terrain: &t,
            folds: &folds,
        };
        let mut player = PlayerController::new();
        player.queue(Action::Drink);
        let (facts, _written) = sys.step_one_with_controller(
            &ledger,
            &npc,
            &mut RoomMeshMemo::new(),
            &mut HomeNavCache::new(),
            &mut RouteMemo::new(),
            &mut player,
        );
        assert!(
            facts.iter().any(|f| f.predicate == DRANK),
            "the queued Drink must reach advance_one and commit, not be eaten \
             by catch_up's own reconstruction pass over the day-0-to-day-3 \
             gap: {facts:?}"
        );
    }

    #[test]
    fn the_recount_surfaces_the_drives_own_provenance_for_the_full_round_trip() {
        // THE PROVENANCE READ, DECOUPLED FROM REAL-WORLD REACHABILITY
        // (the-surmise T4 review): `why`'s recount
        // (`hornvale_historiography::recount`) must surface the drive's own
        // reason for a move AND the drink that satisfied it — proven here
        // directly against `DriveMovements`'s committed facts on PLANTED
        // (guaranteed-one-hop) terrain — a deterministic, seed-independent
        // proof of the mechanism, orthogonal to
        // `seed_42_home_settlements_real_walk_reachability_is_a_measured_t5_finding`'s
        // measurement of the real seed-42 world's own settlement/water
        // placement.
        // THE ROUTE CHANGED UNDER THIS TEST AND IT KEPT PASSING (The
        // Warrant, Task 3) — which is exactly why the assertions below are
        // widened rather than left alone. The gloss "went down to the river
        // it knew (thirst)" used to reach `recount` as the `agent-at` fact's
        // own `provenance`. It now reaches it as the REGISTRY DOC of the
        // `errand/water-known` predicate, because `recount` renders
        // `register_predicate`'s doc string for every predicate it replays.
        // Same words on the same line, different producer — so a test that
        // only greps the transcript can no longer tell you which mechanism
        // put them there, and would have gone on reading green if the flip
        // had lost the gloss and some other fact had happened to carry it.
        // The extra assertions below pin the route itself: the errand fact
        // exists, and the step's provenance is the bare producer name.
        //
        // Mutation-verify: blanking `errand_predicates`'s "went down to the
        // river it knew (thirst)" doc, or `drank_fact`'s "drank from the
        // river (thirst sated)" string, reds ONE of the two transcript
        // assertions below without touching the other. And observed directly
        // 2026-09-05: repointing `errand_key`'s two `Thirst` arms at
        // `ERRAND_HOME` reds the ROUTE assertion first ("the believer's
        // beeline must commit an errand/water-known errand"), which is the
        // assertion added for exactly that mutation — restored and
        // `diff`-confirmed byte-identical afterward.
        // (This test predates The Freshet re-wire; kept on planted terrain
        // deliberately — the mechanism-level provenance read should not
        // depend on any one real seed's fresh-water placement.)
        let mut world = World::new(Seed(0));
        world
            .registry
            .register_predicate(AGENT_AT, false, "pos")
            .unwrap();
        world
            .registry
            .register_predicate(DRANK, false, "drank")
            .unwrap();
        world
            .registry
            .register_predicate(RESTED, false, "rested")
            .unwrap();
        world
            .registry
            .register_predicate(SLEPT, false, "slept")
            .unwrap();
        world
            .registry
            .register_predicate(EATEN, false, "eaten")
            .unwrap();
        for (key, doc) in errand_predicates() {
            world.registry.register_predicate(key, false, doc).unwrap();
        }
        let entity = world
            .ledger
            .mint_entity(test_lineage(world.ledger.entity_count() as u16));
        world
            .ledger
            .commit(
                Fact {
                    subject: entity,
                    predicate: hornvale_kernel::NAME.to_string(),
                    object: Value::Text("herder".to_string()),
                    place: None,
                    day: None,
                    provenance: "test".to_string(),
                },
                &world.registry,
            )
            .unwrap();
        let home = raddr(1.0);
        let water = home.neighbors()[0].clone();
        let npc = Body {
            entity,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home: home.clone(),
            resource: water.clone(),
            species: "goblin".into(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Endothermic,
            niche: default_diet_niche(),
            boldness: 0.5,
            threat_niche: mortal_threat_niche(),
            // The action clock's reference mass (The Action Clock T2): tempo is
            // exactly `1.0` here, so this fixture's timings are unmoved.
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: "herder".into(),
        };
        // Elevation still steers the exploration prior (downhill), separate
        // from fresh-water truth: `water` must be the uniquely lowest
        // neighbor so the first (ignorant) thirsty cycle explores directly
        // onto it, letting a later cycle's believer beeline actually fire
        // "went down to the river it knew (thirst)" below.
        let t = PlantedTerrain {
            elevations: [(water.clone(), 0.0)].into_iter().collect(),
            fresh: [water.clone()].into_iter().collect(),
            ..Default::default()
        };
        let folds = test_folds();
        let sys = DriveMovements {
            npcs: vec![npc],
            from: WorldTime::GENESIS,
            to: WorldTime::from_std_days(40.0).expect("a day value is finite"),
            params: SUSTENANCE,
            // No sky in a planted-terrain fixture: the action clock takes its
            // base rate (spec §4.1).
            day_ticks: None,
            terrain: &t,
            folds: &folds,
        };
        world.ledger = hornvale_kernel::tick(
            &world.ledger,
            &[&sys],
            &["drive-movements"],
            &world.registry,
        )
        .unwrap();
        // THE ROUTE, asserted before the transcript is read: the believer's
        // beeline commits an `errand/water-known` fact, and the steps under
        // it carry the bare producer name rather than any prose. Without
        // these two, the transcript assertions below cannot distinguish the
        // registry doc from some other fact's provenance.
        assert!(
            world
                .ledger
                .facts_of(entity, ERRAND_WATER_KNOWN)
                .next()
                .is_some(),
            "the believer's beeline must commit an {ERRAND_WATER_KNOWN} errand, or the \
             gloss below could only be coming from somewhere else"
        );
        for f in world.ledger.facts_of(entity, AGENT_AT) {
            assert_eq!(
                f.provenance, ERRAND_PRODUCER,
                "a step names its producer, never a reason (The Warrant, Task 3)"
            );
        }
        let recount = hornvale_historiography::recount(&world, entity).expect("facts exist");
        assert!(
            recount.contains("went down to the river it knew (thirst)"),
            "the recount names the drive's own reason for the move — now via the \
             errand predicate's registry doc, not the step's provenance: {recount}"
        );
        assert!(
            recount.contains("drank from the river (thirst sated)"),
            "the recount also names the drink that satisfied the goal: {recount}"
        );
    }

    #[test]
    fn thirsty_but_unreachable_water_gives_up_quickly_not_at_max_steps() {
        // THE ANTI-HANG GUARD (The Foresight T3 review), reinterpreted for
        // belief (The Surmise): under the OLD ground-truth model, unreachable
        // water made `decide` return `Hold` immediately and the idle-jump's
        // strict-progress guard fired on that very first Hold. Under the
        // belief model an IGNORANT agent no longer "gives up" on water it has
        // never reached — it EXPLORES instead — so a genuinely water-less
        // world (all-INFINITY terrain: no water anywhere for the agent to
        // ever discover) exercises the OTHER termination guarantee: the
        // unconditional `steps >= MAX_STEPS` cap bounds the walk even though
        // it never reaches "thirsty and known-unreachable" in the old sense.
        // The load-bearing assertion is boundedness/termination, not an
        // exact fact count (an ignorant agent commits real exploration moves
        // now, where it once committed none).
        let mut reg = hornvale_kernel::ConceptRegistry::default();
        reg.register_predicate(AGENT_AT, false, "pos").unwrap();
        reg.register_predicate(DRANK, false, "drank").unwrap();
        reg.register_predicate(RESTED, false, "rested").unwrap();
        reg.register_predicate(SLEPT, false, "slept").unwrap();
        reg.register_predicate(EATEN, false, "eaten").unwrap();
        for (key, doc) in errand_predicates() {
            reg.register_predicate(key, false, doc).unwrap();
        }
        let ledger = Ledger::default();
        let e = EntityId::new(1).unwrap();
        let home = raddr(1.0);
        let water = Facet::containing([-1.0, 0.0, 0.0], 6); // irrelevant now: no water exists anywhere
        let npc = Body {
            entity: e,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home: home.clone(),
            resource: water,
            species: "goblin".into(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Endothermic,
            niche: default_diet_niche(),
            boldness: 0.5,
            threat_niche: mortal_threat_niche(),
            // The action clock's reference mass (The Action Clock T2): tempo is
            // exactly `1.0` here, so this fixture's timings are unmoved.
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: "herder".into(),
        };
        // No fresh water anywhere, so belief never forms and the agent
        // explores for the whole run.
        let t = PlantedTerrain::fresh_only(std::iter::empty());
        // A long wait: the MAX_STEPS cap (not the wait) must be what bounds
        // this — if it weren't a real backstop, work would scale with the
        // wait instead.
        let folds = test_folds();
        let sys = DriveMovements {
            npcs: vec![npc],
            from: WorldTime::GENESIS,
            to: WorldTime::from_std_days(10_000.0).expect("a day value is finite"),
            params: SUSTENANCE,
            // No sky in a planted-terrain fixture: the action clock takes its
            // base rate (spec §4.1).
            day_ticks: None,
            terrain: &t,
            folds: &folds,
        };
        let next = hornvale_kernel::tick(&ledger, &[&sys], &["drive-movements"], &reg).unwrap();
        // Never drinks (no water exists); the walk is bounded by MAX_STEPS —
        // the tick's own prompt return here (within this test's harness
        // timeout) is additional proof it didn't hang, but the real
        // assertion is the explicit bound below, not an exact fact count.
        let drank_count = next.find(DRANK).filter(|f| f.subject == e).count();
        assert_eq!(drank_count, 0, "no water exists so the agent never drinks");
        let moves = next.find(AGENT_AT).filter(|f| f.subject == e).count();
        assert!(
            moves <= MAX_STEPS,
            "the MAX_STEPS cap must bound the exploring walk; got {moves} moves"
        );
    }

    #[test]
    fn a_degenerate_zero_rise_drive_terminates_via_the_max_steps_cap_not_a_hang() {
        // THE DEGENERATE-DRIVEPARAMS REGRESSION (The Foresight T3 review):
        // `rise: 0.0, act: 0.0` makes the `Hold`-idle jump compute
        // `next_act = last_drank + act / rise = 0.0 / 0.0 = NaN`. Every NaN
        // comparison (`<=`, `>`) is `false`, so BOTH strict-progress guards
        // in the `Hold` arm (`next_act <= day` and `next_act > self.to.day`)
        // fail to fire, and `day = next_act` sets `day` to NaN too (which
        // then also never exceeds `self.to.day`, since any comparison with
        // NaN is false). Only the unconditional `steps >= MAX_STEPS` cap
        // (10_000) stops the loop — this test proves that cap is the real
        // backstop, not the closed-form guard (which is a no-op here).
        //
        // Under action-centric arbitration (The Temperament): `drive == 0.0`
        // is "thirst active" by the threshold (`0.0 >= act == 0.0`), but its
        // CAPPED urgency is `0.0`, so EVERY action's utility is
        // `weight × 0.0 × serviceability == 0.0` — a zero-pressure drive drives
        // nothing. Arbitration therefore returns `Hold` on every step (rather
        // than the old model's blind explore-move, which stepped regardless of
        // urgency magnitude), and the walk terminates purely through the Hold
        // arm's non-finite idle-jump guard (`act / rise == 0.0 / 0.0 == NaN`
        // → `continue`), bounded by the unconditional `steps >= MAX_STEPS` cap.
        // This exercises the NaN-guard/Hold-spin path DIRECTLY — a stronger
        // termination proof than the old explore-move spin, and the correct
        // behaviour: no felt pressure, no motion.
        //
        // The old regression test for this class
        // (`a_misconfigured_drive_terminates_instead_of_hanging`, keyed on
        // `sated >= act`) no longer applies: the planned model's `decide`
        // never reads `sated`, so that degenerate class can't hang it. This
        // is the new degenerate class the planned model is actually exposed
        // to.
        let mut reg = hornvale_kernel::ConceptRegistry::default();
        reg.register_predicate(AGENT_AT, false, "pos").unwrap();
        reg.register_predicate(DRANK, false, "drank").unwrap();
        reg.register_predicate(RESTED, false, "rested").unwrap();
        reg.register_predicate(SLEPT, false, "slept").unwrap();
        reg.register_predicate(EATEN, false, "eaten").unwrap();
        for (key, doc) in errand_predicates() {
            reg.register_predicate(key, false, doc).unwrap();
        }
        let ledger = Ledger::default();
        let e = EntityId::new(1).unwrap();
        let home = raddr(1.0);
        let water = home.neighbors()[0].clone();
        let npc = Body {
            entity: e,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home: home.clone(),
            resource: water,
            species: "goblin".into(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Endothermic,
            niche: default_diet_niche(),
            boldness: 0.5,
            threat_niche: mortal_threat_niche(),
            // The action clock's reference mass (The Action Clock T2): tempo is
            // exactly `1.0` here, so this fixture's timings are unmoved.
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: "herder".into(),
        };
        // No fresh water anywhere, so belief never forms.
        let t = PlantedTerrain::fresh_only(std::iter::empty());
        let degenerate = DriveParams {
            rise: 0.0,
            act: 0.0,
        };
        // A long interval: if MAX_STEPS were not the backstop, this would
        // spin forever (this test's own short harness timeout is additional
        // proof it didn't hang; the assertion below is the load-bearing
        // one).
        let folds = test_folds();
        let sys = DriveMovements {
            npcs: vec![npc],
            from: WorldTime::GENESIS,
            to: WorldTime::from_std_days(1_000_000.0).expect("a day value is finite"),
            params: degenerate,
            // No sky in a planted-terrain fixture: the action clock takes its
            // base rate (spec §4.1).
            day_ticks: None,
            terrain: &t,
            folds: &folds,
        };
        let next = hornvale_kernel::tick(&ledger, &[&sys], &["drive-movements"], &reg).unwrap();
        // The load-bearing proof is that the call above RETURNED at all — with
        // a 1_000_000-day interval, only the `steps >= MAX_STEPS` cap can bound
        // the NaN-guarded Hold-spin; a real hang would time this test out. The
        // committed-fact count is exactly ZERO: a zero-urgency drive drives
        // nothing (every action's utility is `× 0.0 == 0.0` → Hold), so no
        // `agent-at`/`drank` is ever emitted — the correct behaviour, and
        // trivially within the MAX_STEPS bound.
        let moves = next.find(AGENT_AT).filter(|f| f.subject == e).count();
        let drinks = next.find(DRANK).filter(|f| f.subject == e).count();
        assert!(
            moves + drinks <= MAX_STEPS,
            "the MAX_STEPS cap must bound total committed facts even under a \
             NaN-producing degenerate DriveParams; got {moves} moves + {drinks} drinks"
        );
        assert_eq!(
            moves + drinks,
            0,
            "a zero-urgency (zero-pressure) drive drives nothing: arbitration \
             Holds every step and the walk terminates via the bounded NaN-guard \
             Hold-spin, committing no facts"
        );
    }

    #[test]
    fn moves_carry_drive_naming_provenance() {
        let p = SUSTENANCE;
        let mut ledger = Ledger::default();
        let mut reg = hornvale_kernel::ConceptRegistry::default();
        reg.register_predicate(AGENT_AT, false, "pos").unwrap();
        reg.register_predicate(DRANK, false, "drank").unwrap();
        reg.register_predicate(RESTED, false, "rested").unwrap();
        reg.register_predicate(SLEPT, false, "slept").unwrap();
        reg.register_predicate(EATEN, false, "eaten").unwrap();
        for (key, doc) in errand_predicates() {
            reg.register_predicate(key, false, doc).unwrap();
        }
        let e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
        let home = addr(1.0);
        let resource = home.neighbors()[0].clone();
        let npc = Body {
            entity: e,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home: home.clone(),
            resource: resource.clone(),
            species: "goblin".into(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Endothermic,
            niche: default_diet_niche(),
            boldness: 0.5,
            threat_niche: mortal_threat_niche(),
            // The action clock's reference mass (The Action Clock T2): tempo is
            // exactly `1.0` here, so this fixture's timings are unmoved.
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: "herder".into(),
        };
        let t = PlantedTerrain::fresh_only([resource.clone()]);
        let folds = test_folds();
        let sys = DriveMovements {
            npcs: vec![npc],
            from: WorldTime::GENESIS,
            to: WorldTime::from_std_days(10.0).expect("a day value is finite"),
            params: p,
            // No sky in a planted-terrain fixture: the action clock takes its
            // base rate (spec §4.1).
            day_ticks: None,
            terrain: &t,
            folds: &folds,
        };
        let next = hornvale_kernel::tick(&ledger, &[&sys], &["drive-movements"], &reg).unwrap();
        let first = next.find(AGENT_AT).find(|f| f.subject == e).unwrap();
        // THE FIELD MOVED, THE CLAIM DID NOT (The Warrant, Task 3). This
        // assertion used to read `first.provenance.contains("thirst")` — the
        // move's own provenance was the authored gloss. It is
        // `vessel/liveness` now, so the claim "a move names the drive that
        // caused it" is re-pointed at the ERRAND fact covering that move,
        // which is where the drive's identity actually lives. The test is
        // NOT deleted and re-added: what it pinned (a thirst-driven step is
        // attributable to thirst) is pinned here, on the new carrier, plus
        // the step's own field asserted exactly so the old carrier cannot
        // quietly come back.
        //
        // TWO MUTATIONS, both observed red 2026-09-05, target text asserted
        // present before substituting, file `diff`-confirmed byte-identical
        // after:
        //   (1) `errand_key`'s two `Thirst` arms -> `ERRAND_HOME`. Red: "the
        //       errand covering the first move names the thirst drive:
        //       errand/home". This is the mutation of what the OLD assertion
        //       pinned — a thirst-driven step attributable to thirst — and it
        //       is exactly what the old form could NOT have caught, since it
        //       read `prose_for`'s output and `prose_for` carried no errand
        //       key at all.
        //   (2) the `MoveTo` commit's provenance -> "went down to the river
        //       it knew (thirst)". Red: "a move names its producer, never a
        //       drive". The OLD assertion (`contains("thirst")`) would have
        //       PASSED on this one, which is the sense in which the re-point
        //       is a strict gain rather than a translation.
        assert_eq!(
            first.provenance, ERRAND_PRODUCER,
            "a move names its producer, never a drive: {}",
            first.provenance
        );
        let errand = errand_predicates()
            .iter()
            .filter_map(|(key, _)| next.facts_of(e, key).next().map(|f| (*key, f.day)))
            .min_by_key(|(_, day)| *day)
            .map(|(key, _)| key)
            .expect("a move commits an errand covering it");
        assert!(
            errand == ERRAND_WATER_KNOWN || errand == ERRAND_WATER_BLIND,
            "the errand covering the first move names the thirst drive: {errand}"
        );
        let _ = ledger;
    }

    #[test]
    fn plan_to_water_is_a_precondition_chain_move_then_drink() {
        // Water is a mesh neighbor of home (one step away): plan is [MoveTo(water), Drink].
        let home = raddr(1.0);
        let water = home.neighbors()[0].clone();
        let plan = plan_to_water(&home, &water, 10_000, &std::collections::BTreeSet::new())
            .expect("reachable");
        assert_eq!(plan.len(), 2);
        assert!(matches!(plan[0], Action::MoveTo(ref r) if *r == water));
        assert!(matches!(plan[1], Action::Drink));
    }

    #[test]
    fn plan_to_water_when_already_there_is_just_drink() {
        let water = raddr(1.0);
        let plan =
            plan_to_water(&water, &water, 10_000, &std::collections::BTreeSet::new()).unwrap();
        assert_eq!(plan, vec![Action::Drink]);
    }

    #[test]
    fn every_action_in_a_plan_has_its_precondition_satisfied_in_sequence() {
        // Execute the plan from `home`, checking each action's precondition holds in
        // order (the precondition-chain validity: Drink is only ever preceded by
        // arrival at water). Water two rooms away for a genuine multi-step chain.
        let home = raddr(1.0);
        let mid = home.neighbors()[0].clone();
        let water = mid
            .neighbors()
            .iter()
            .find(|n| **n != home)
            .unwrap()
            .clone();
        let plan = plan_to_water(&home, &water, 10_000, &std::collections::BTreeSet::new())
            .expect("reachable");
        let mut pos = home.clone();
        let mut hydrated = false;
        for a in &plan {
            match a {
                Action::MoveTo(n) => {
                    assert!(
                        pos.neighbors().contains(n),
                        "MoveTo precondition: adjacency"
                    );
                    pos = n.clone();
                }
                Action::Drink => {
                    assert_eq!(pos, water, "Drink precondition: at water");
                    hydrated = true;
                }
                Action::Rest | Action::Sleep | Action::Eat => {
                    unreachable!("plan_to_water never emits Rest, Sleep or Eat")
                }
                Action::MoveWithin(_) => {
                    unreachable!("plan_to_water never emits MoveWithin (The Threshold task 6+)")
                }
                Action::Why
                | Action::Npcs
                | Action::Help
                | Action::Eyes
                | Action::Whoami
                | Action::Provoke
                | Action::Soothe
                | Action::ObjectiveMap
                | Action::ObjectiveExamine
                | Action::ObjectiveNeeds
                | Action::ObjectiveWait
                | Action::ObjectiveLook
                | Action::ObjectiveKnows => {
                    unreachable!("plan_to_water never emits a player-only act (The Deed)")
                }
            }
        }
        assert!(hydrated, "the plan achieves the goal");
        assert!(
            plan.len() >= 3,
            "multi-step: at least two moves then a drink"
        );
    }

    #[test]
    fn plan_to_room_is_pure_navigation_no_drink() {
        let home = raddr(1.0);
        let dest = home.neighbors()[0].clone();
        let plan = plan_to_room(&home, &dest, 10_000, &std::collections::BTreeSet::new()).unwrap();
        assert!(plan.iter().all(|a| matches!(a, Action::MoveTo(_))));
        assert!(!plan.is_empty());
    }

    #[test]
    fn planner_routes_around_a_remembered_cell() {
        // THE SHUN: a remembered-dangerous room on the straight path becomes a
        // finite detour cost, so the A* routes AROUND it when a cheaper detour
        // exists — and with an EMPTY avoid set the plan is unchanged (the
        // byte-identity property, at the planner seam).
        let home = raddr(1.0);
        let mid = home.neighbors()[0].clone();
        let water = mid
            .neighbors()
            .iter()
            .find(|n| **n != home)
            .unwrap()
            .clone(); // 2 hops from home, via `mid`
        let empty = std::collections::BTreeSet::new();
        let direct = plan_to_water(&home, &water, 10_000, &empty).expect("reachable");
        assert_eq!(
            direct.len(),
            3,
            "the straight path is two moves then a drink"
        );
        // The via-room the straight plan actually steps through (not water itself).
        let via = direct
            .iter()
            .find_map(|a| match a {
                Action::MoveTo(r) if *r != water => Some(r.clone()),
                _ => None,
            })
            .expect("a via-room on the straight path");
        let mut avoid = std::collections::BTreeSet::new();
        avoid.insert(via.clone());
        let around = plan_to_water(&home, &water, 10_000, &avoid).expect("still reachable");
        assert!(
            !around
                .iter()
                .any(|a| matches!(a, Action::MoveTo(r) if *r == via)),
            "the plan routes AROUND the remembered room"
        );
        assert!(
            matches!(around.last(), Some(Action::Drink)),
            "the detour still reaches water and drinks"
        );
        assert!(
            around.len() >= direct.len(),
            "the detour costs at least as much as the straight path"
        );
    }

    #[test]
    fn planner_braves_it_when_the_detour_exceeds_the_penalty() {
        // SURVIVAL-OVERRIDE FOR FREE: the penalty is FINITE, so when the
        // remembered-bad room is the ONLY route to water (no detour at all — an
        // infinite alternative), the creature still takes it. A dying-thirsty
        // creature braves the haunted ground; the flinch is a preference, not a
        // wall.
        let home = raddr(1.0);
        let water = home.neighbors()[0].clone(); // 1 hop — MoveTo(water) is the sole route in
        let mut avoid = std::collections::BTreeSet::new();
        avoid.insert(water.clone());
        let plan =
            plan_to_water(&home, &water, 10_000, &avoid).expect("the finite penalty never traps");
        assert_eq!(
            plan,
            vec![Action::MoveTo(water.clone()), Action::Drink],
            "braves the remembered room when it is the only route"
        );
    }

    #[test]
    fn the_shun_a_frightened_creature_detours_around_remembered_ground_a_control_goes_through() {
        // THE SHUN, end-to-end through the real DriveMovements tick (spec §e2e):
        // a creature frightened at a room X on an early trip plans its LATER
        // journeys to water AROUND X — proactively — while an otherwise-identical
        // control that never stood at X takes the straight path THROUGH it. Both
        // reach water (the frightened one is never trapped — the finite penalty is
        // a preference, not a wall). X is only MILDLY hazardous (0.4, just over
        // DANGER_ACT): enough that the memory forms and a dying-thirsty control
        // reactively pushes through it, but not lethal (that would make the
        // control route around reactively too — the keystone
        // `danger_routes_a_thirsty_creature_around_a_hazard_to_water` case).
        let mut reg = hornvale_kernel::ConceptRegistry::default();
        reg.register_predicate(AGENT_AT, false, "pos").unwrap();
        reg.register_predicate(DRANK, false, "drank").unwrap();
        reg.register_predicate(RESTED, false, "rested").unwrap();
        reg.register_predicate(SLEPT, false, "slept").unwrap();
        reg.register_predicate(EATEN, false, "eaten").unwrap();
        for (key, doc) in errand_predicates() {
            reg.register_predicate(key, false, doc).unwrap();
        }

        // Geometry: discover the straight S→W path (hazard-free planning) and pick
        // an INTERIOR room X (distance 2 from S) as the frightening ground. X is
        // not adjacent to S or W, so standing at S/W is never itself frightening
        // (`threat_field` maxes over neighbours) — the remembered set is exactly
        // {X}.
        let start = raddr(1.0);
        // Chain neighbours to a distant water room, then take the true shortest
        // path so an interior room is guaranteed.
        let c1 = start.neighbors()[0].clone();
        let c2 = c1
            .neighbors()
            .iter()
            .find(|n| **n != start)
            .unwrap()
            .clone();
        let c3 = c2
            .neighbors()
            .iter()
            .find(|n| **n != c1 && **n != start)
            .unwrap()
            .clone();
        let water = c3
            .neighbors()
            .iter()
            .find(|n| **n != c2 && **n != c1 && **n != start)
            .unwrap()
            .clone();
        let empty = std::collections::BTreeSet::new();
        let straight = plan_to_room(&start, &water, PLAN_BUDGET, &empty).expect("reachable");
        assert!(
            straight.len() >= 4,
            "need a path with an interior room not adjacent to either endpoint"
        );
        let path_rooms: Vec<Facet> = straight
            .iter()
            .map(|a| match a {
                Action::MoveTo(r) => r.clone(),
                _ => unreachable!("plan_to_room emits only MoveTo"),
            })
            .collect();
        let x = path_rooms[1].clone(); // distance 2 from start ⇒ not adjacent to start; ≥2 from water
        assert!(
            !start.neighbors().contains(&x) && !water.neighbors().contains(&x),
            "X must be interior (not adjacent to start or water)"
        );

        // Terrain: fresh water at W, a MILD uncanny hazard at X. The planner reads
        // only the avoid-set, not the terrain hazard, so the control's straight
        // plan still runs through X; the hazard drives only the reactive Danger
        // drive during the walk.
        let terrain = PlantedTerrain::hazard([water.clone()], [(x.clone(), 0.4)]);

        // A steady mortal creature; home == start so homing does not pull it off X.
        let npc_at = |entity: EntityId| Body {
            entity,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home: start.clone(),
            resource: water.clone(),
            species: "goblin".into(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Endothermic,
            niche: default_diet_niche(),
            boldness: 0.5,
            threat_niche: mortal_threat_niche(),
            // The action clock's reference mass (The Action Clock T2): tempo is
            // exactly `1.0` here, so this fixture's timings are unmoved.
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: "wanderer".into(),
        };

        // Run one creature forward over a multi-cycle window and return (ledger,
        // entity). `remember_x` seeds a committed visit to X (day 0.15), so the
        // frightened creature's believed_hazard is {X}; the control never stood
        // there. Both know water (a committed visit to W) and start at S.
        let run = |remember_x: bool| -> (Ledger, EntityId) {
            let mut ledger = Ledger::default();
            let e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
            commit_agent_at(&mut ledger, &reg, e, &water, 0.1); // knows water
            if remember_x {
                commit_agent_at(&mut ledger, &reg, e, &x, 0.15); // frightened here → remembers X
            }
            commit_agent_at(&mut ledger, &reg, e, &start, 0.2); // now at start
            let folds = test_folds();
            let sys = DriveMovements {
                npcs: vec![npc_at(e)],
                from: WorldTime::from_std_days(1.0).expect("a day value is finite"), // after the seeded history
                to: WorldTime::from_std_days(60.0).expect("a day value is finite"), // several thirst cycles (act/rise ≈ 5.7 days)
                params: SUSTENANCE,
                // No sky in a planted-terrain fixture: the action clock takes its
                // base rate (spec §4.1).
                day_ticks: None,
                terrain: &terrain,
                folds: &folds,
            };
            let next = hornvale_kernel::tick(&ledger, &[&sys], &["drive-movements"], &reg).unwrap();
            (next, e)
        };

        // The committed positions the tick EMITTED (day ≥ from), decoded to rooms.
        let walked = |ledger: &Ledger, e: EntityId| -> Vec<Facet> {
            ledger
                .find(AGENT_AT)
                .filter(|f| f.subject == e)
                .filter(|f| f.day.map(|d| d.as_std_days() >= 1.0).unwrap_or(false))
                .filter_map(|f| match &f.object {
                    Value::Text(s) => Some(room_from_text(s)),
                    _ => None,
                })
                .collect()
        };
        let drinks =
            |ledger: &Ledger, e: EntityId| ledger.find(DRANK).filter(|f| f.subject == e).count();

        // Confirmed sanity: believed_hazard is exactly {X} for the frightened
        // creature and empty for the control (the one-source-of-truth fold).
        {
            let mut fl = Ledger::default();
            let fe = fl.mint_entity(test_lineage(fl.entity_count() as u16));
            commit_agent_at(&mut fl, &reg, fe, &water, 0.1);
            commit_agent_at(&mut fl, &reg, fe, &x, 0.15);
            commit_agent_at(&mut fl, &reg, fe, &start, 0.2);
            let n = npc_at(fe);
            let hz = believed_hazard(
                &fl,
                &test_folds(),
                &n,
                WorldTime::from_std_days(1.0).expect("a day value is finite"),
                &terrain,
                &[],
            );
            assert_eq!(
                hz.into_iter().collect::<Vec<_>>(),
                vec![x.clone()],
                "the frightened creature remembers exactly X"
            );
        }

        let (frightened_led, fe) = run(true);
        let (control_led, ce) = run(false);

        let frightened_path = walked(&frightened_led, fe);
        let control_path = walked(&control_led, ce);

        // (a) Both reach water and drink — the frightened one is NEVER trapped.
        assert!(
            drinks(&frightened_led, fe) >= 1,
            "the frightened creature still reaches water (the detour is finite)"
        );
        assert!(drinks(&control_led, ce) >= 1, "the control reaches water");
        // (b) The frightened creature's LATER journeys detour AROUND X — no
        // tick-emitted position is X.
        assert!(
            !frightened_path.contains(&x),
            "the frightened creature routes around remembered ground X"
        );
        // (c) The control, with no memory of X, takes the straight path THROUGH X
        // (mildly hazardous ground a dying-thirsty creature pushes across).
        assert!(
            control_path.contains(&x),
            "the never-frightened control blunders straight through X"
        );
    }

    #[test]
    fn the_phantom_detours_around_a_passed_alarm_then_relearns_the_ground_safe() {
        // THE PHANTOM, end-to-end through the real DriveMovements tick (spec §e2e):
        // a creature alarm-frightened at a now-SAFE room X — where a herd-mate B
        // briefly panicked beside it — plans its LATER journeys to water AROUND X,
        // shunning ground that is no longer dangerous (the phobia, a fear of
        // nothing). A control that never stood at X blunders straight through. And
        // once the creature safely REVISITS X (the alarm long gone), the detour
        // ceases — the fear disproved. UNLIKE THE SHUN, X carries NO terrain
        // hazard: the danger is transient, re-derived from B's committed PAST
        // position, and gone by planning time.
        let mut reg = hornvale_kernel::ConceptRegistry::default();
        reg.register_predicate(AGENT_AT, false, "pos").unwrap();
        reg.register_predicate(DRANK, false, "drank").unwrap();
        reg.register_predicate(RESTED, false, "rested").unwrap();
        reg.register_predicate(SLEPT, false, "slept").unwrap();
        reg.register_predicate(EATEN, false, "eaten").unwrap();
        for (key, doc) in errand_predicates() {
            reg.register_predicate(key, false, doc).unwrap();
        }

        // Geometry (as THE SHUN): the straight S→W path, X an interior room not
        // adjacent to either endpoint (so standing at S/W is never frightening).
        let PhantomGeometry {
            start,
            water,
            x,
            p0,
            p2,
            d_room,
            hazard_e,
        } = phantom_geometry();
        let far = raddr(-1.0);
        let terrain = PlantedTerrain::hazard([water.clone()], [(hazard_e.clone(), 0.8)]);

        // A steady mortal; home == start so homing does not pull it off course.
        let npc_at = |entity: EntityId| Body {
            entity,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home: start.clone(),
            resource: water.clone(),
            species: "goblin".into(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Endothermic,
            niche: default_diet_niche(),
            boldness: BOLDNESS_STEADY,
            threat_niche: mortal_threat_niche(),
            // The action clock's reference mass (The Action Clock T2): tempo is
            // exactly `1.0` here, so this fixture's timings are unmoved.
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: "wanderer".into(),
        };
        // The herd-mate B: knows water (so it beelines and settles, bounded), and
        // is the transient alarm source when standing at D.
        let emitter_npc = |entity: EntityId| Body {
            entity,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home: far.clone(),
            resource: water.clone(),
            species: "goblin".into(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Endothermic,
            niche: default_diet_niche(),
            boldness: BOLDNESS_STEADY,
            threat_niche: mortal_threat_niche(),
            // The action clock's reference mass (The Action Clock T2): tempo is
            // exactly `1.0` here, so this fixture's timings are unmoved.
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: "herd-mate".into(),
        };

        // Guard: every room on the straight path is terrain-SAFE — the phantom is
        // a fear of nothing, never a static Haunt (empty-roster verdict is FALSE).
        let dummy = npc_at(EntityId::new(1).unwrap());
        let empty_ledger = Ledger::default();
        for room in [&start, &p0, &x, &p2, &water] {
            assert!(
                !frightened_at(
                    room,
                    &dummy,
                    &terrain,
                    WorldTime::from_std_days(1.0).expect("a day value is finite"),
                    &[],
                    &empty_ledger,
                    &test_folds()
                ),
                "path room {room:?} must be terrain-safe (no static hazard)"
            );
        }

        // Sanity: the phantom forms exactly at X. Terrain-only memory is empty
        // (X is safe ground); with the roster, the re-derived PAST alarm — B at D
        // on day 0.35 — makes X remembered-dangerous though it is now safe.
        {
            let mut fl = Ledger::default();
            let a = fl.mint_entity(test_lineage(fl.entity_count() as u16));
            commit_agent_at(&mut fl, &reg, a, &water, 0.30);
            commit_agent_at(&mut fl, &reg, a, &x, 0.35);
            commit_agent_at(&mut fl, &reg, a, &start, 0.40);
            let b = fl.mint_entity(test_lineage(fl.entity_count() as u16));
            commit_agent_at(&mut fl, &reg, b, &d_room, 0.35);
            commit_agent_at(&mut fl, &reg, b, &far, 0.40);
            let an = npc_at(a);
            let bn = emitter_npc(b);
            assert!(
                believed_hazard(
                    &fl,
                    &test_folds(),
                    &an,
                    WorldTime::from_std_days(1.0).expect("a day value is finite"),
                    &terrain,
                    &[]
                )
                .is_empty(),
                "terrain-only memory is empty — X is a fear of nothing"
            );
            let hz = believed_hazard(
                &fl,
                &test_folds(),
                &an,
                WorldTime::from_std_days(1.0).expect("a day value is finite"),
                &terrain,
                std::slice::from_ref(&bn),
            );
            assert_eq!(
                hz.into_iter().collect::<Vec<_>>(),
                vec![x.clone()],
                "the phantom: X is remembered-dangerous, re-derived from B's past panic"
            );
        }

        // Run one rememberer (+ the herd-mate B) forward over a multi-cycle window.
        // `remember` seeds the frightened visit to X (day 0.35, B beside it);
        // `disprove` adds a later SAFE revisit (day 2.35, B long gone).
        let run = |remember: bool, disprove: bool| -> (Ledger, EntityId, f64) {
            let from_day = if disprove { 3.0 } else { 1.0 };
            let mut ledger = Ledger::default();
            let a = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
            commit_agent_at(&mut ledger, &reg, a, &water, 0.30); // knows water
            if remember {
                commit_agent_at(&mut ledger, &reg, a, &x, 0.35); // frightened by B's alarm
            }
            if disprove {
                commit_agent_at(&mut ledger, &reg, a, &x, 2.35); // SAFE revisit (B gone)
            }
            commit_agent_at(
                &mut ledger,
                &reg,
                a,
                &start,
                if disprove { 2.40 } else { 0.40 },
            );
            let mut npcs = vec![npc_at(a)];
            if remember {
                // B: knows water, panics beside X at 0.35, gone to far ground by
                // 0.40 — so X is SAFE at planning time. Only present when there is
                // a memory to re-derive (the control needs no alarm source).
                let b = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
                commit_agent_at(&mut ledger, &reg, b, &water, 0.29);
                commit_agent_at(&mut ledger, &reg, b, &d_room, 0.35);
                commit_agent_at(&mut ledger, &reg, b, &far, 0.40);
                npcs.push(emitter_npc(b));
            }
            let folds = test_folds();
            let sys = DriveMovements {
                npcs,
                from: WorldTime::from_std_days(from_day).expect("a day value is finite"),
                to: WorldTime::from_std_days(60.0).expect("a day value is finite"), // several thirst cycles (act/rise ≈ 5.7 days)
                params: SUSTENANCE,
                // No sky in a planted-terrain fixture: the action clock takes its
                // base rate (spec §4.1).
                day_ticks: None,
                terrain: &terrain,
                folds: &folds,
            };
            let next = hornvale_kernel::tick(&ledger, &[&sys], &["drive-movements"], &reg).unwrap();
            (next, a, from_day)
        };

        // The committed positions the tick EMITTED (day ≥ from), decoded to rooms.
        let walked = |ledger: &Ledger, e: EntityId, from_day: f64| -> Vec<Facet> {
            ledger
                .find(AGENT_AT)
                .filter(|f| f.subject == e)
                .filter(|f| f.day.map(|d| d.as_std_days() >= from_day).unwrap_or(false))
                .filter_map(|f| match &f.object {
                    Value::Text(s) => Some(room_from_text(s)),
                    _ => None,
                })
                .collect()
        };
        let drinks =
            |ledger: &Ledger, e: EntityId| ledger.find(DRANK).filter(|f| f.subject == e).count();

        let (frightened_led, fe, ffrom) = run(true, false);
        let (control_led, ce, cfrom) = run(false, false);
        let (disproved_led, de, dfrom) = run(true, true);

        let frightened_path = walked(&frightened_led, fe, ffrom);
        let control_path = walked(&control_led, ce, cfrom);
        let disproved_path = walked(&disproved_led, de, dfrom);

        // Everyone reaches water — the phantom-shunning creature is NEVER trapped
        // (the memory penalty is finite, a preference, not a wall).
        assert!(
            drinks(&frightened_led, fe) >= 1,
            "the frightened creature still reaches water (the detour is finite)"
        );
        assert!(drinks(&control_led, ce) >= 1, "the control reaches water");
        assert!(
            drinks(&disproved_led, de) >= 1,
            "after the disproof the creature still reaches water"
        );

        // (a) THE PHANTOM: later journeys DETOUR around the now-safe X, where a
        // never-alarmed control goes straight THROUGH it.
        assert!(
            !frightened_path.contains(&x),
            "the phantom: routes AROUND ground where a passed alarm once frightened it"
        );
        assert!(
            control_path.contains(&x),
            "the never-alarmed control blunders straight through the safe X"
        );
        // (b) THE DISPROOF: once X is safely revisited, the most-recent visit is
        // safe, the phantom clears, and the detour ceases — through X again.
        assert!(
            disproved_path.contains(&x),
            "the disproof: a safe revisit clears the phantom — X is braved again"
        );
    }

    #[test]
    fn the_shudder_is_felt_on_the_phantom_then_discharged_then_disproven() {
        // THE SHUDDER, end-to-end: the full arc The Phantom could only plan, in
        // the SAME world it could only route around.
        //   (1) FELT       — standing on X, where herd-mate B once panicked
        //                    beside it, the creature reads Danger though X's own
        //                    terrain is safe and B is long gone. Fear of nothing
        //                    present.
        //   (2) DISCHARGED — it is not stuck: its affect is not a distress label,
        //                    and the drive offers a step OFF X, not a Hold.
        //   (3) DISPROVEN  — having stood there and come to no harm, the room
        //                    leaves both the shunned set and the dread map: the
        //                    fear the avoidance had been protecting is undone by
        //                    the one experience that can undo it.
        let mut reg = hornvale_kernel::ConceptRegistry::default();
        reg.register_predicate(AGENT_AT, false, "pos").unwrap();
        reg.register_predicate(DRANK, false, "drank").unwrap();
        reg.register_predicate(RESTED, false, "rested").unwrap();
        reg.register_predicate(SLEPT, false, "slept").unwrap();
        reg.register_predicate(EATEN, false, "eaten").unwrap();
        for (key, doc) in errand_predicates() {
            reg.register_predicate(key, false, doc).unwrap();
        }

        // GEOMETRY — copied verbatim from
        // `the_phantom_detours_around_a_passed_alarm_then_relearns_the_ground_safe`
        // above: the straight S→W path, X an interior room, D its off-path
        // neighbour, E the hazard beside D (so X itself is terrain-SAFE and the
        // only thing that ever frightened anyone there was B's passing panic).
        let PhantomGeometry {
            start: _,
            water,
            x,
            p0: _,
            p2: _,
            d_room,
            hazard_e,
        } = phantom_geometry();
        let far = raddr(-1.0);
        let terrain = PlantedTerrain::hazard([water.clone()], [(hazard_e.clone(), 0.8)]);

        let npc_at = |entity: EntityId, home: Facet, label: &str| Body {
            entity,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home,
            resource: water.clone(),
            species: "goblin".into(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Endothermic,
            niche: default_diet_niche(),
            boldness: BOLDNESS_STEADY,
            threat_niche: mortal_threat_niche(),
            // The action clock's reference mass (The Action Clock T2): tempo is
            // exactly `1.0` here, so this fixture's timings are unmoved.
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: label.into(),
        };

        // THE TIMING (the trap T3 charted): the fixture sits in DAYLIGHT at a
        // low-thirst hour. A sleeping Diurnal emitter pursues rest, not fear, and
        // emits nothing; by a late day thirst has saturated and wins arbitration
        // outright, drowning the shudder out.
        let mut ledger = Ledger::default();
        // B: primary-afraid at D (beside the hazard E) on day 0.45, and far away
        // by 0.55 — so at `now` the ground is unremarkable and B is long gone.
        let b_e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
        let b = npc_at(b_e, far.clone(), "herd-mate");
        commit_agent_at(&mut ledger, &reg, b_e, &d_room, 0.45);
        commit_agent_at(&mut ledger, &reg, b_e, &far, 0.55);
        // A: stood at X while B panicked beside it — and has NOT moved since. It
        // gets no safe revisit before `now`: that revisit is exactly the staleness
        // disproof, so granting one early would empty the memory before the test
        // could feel anything. Homed AT X, so the walk that discharges the dread
        // also brings it back to the ground it fears.
        let a_e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
        let a = npc_at(a_e, x.clone(), "rememberer");
        commit_agent_at(&mut ledger, &reg, a_e, &x, 0.45);

        let now = WorldTime::from_std_days(0.6).expect("a day value is finite");
        let band = [a.clone(), b.clone()];

        // (1) FELT.
        let felt = affect_of(&ledger, &test_folds(), &a, &band, now, &terrain);
        assert_eq!(
            felt.object,
            Some(DriveKind::Danger),
            "the rememberer is afraid on now-safe ground: {felt:?}"
        );
        assert!(felt.arousal >= DANGER_ACT, "and it is FELT: {felt:?}");
        assert!(
            threat_field(&x, &a.threat_niche, &terrain) * mettle_factor(a.boldness) < DANGER_ACT,
            "X's PRESENT terrain is not frightening — the fear is memory, not sense"
        );

        // (2) DISCHARGED — a feeling with an outlet, not a pathology.
        assert!(
            !matches!(
                felt.label,
                AffectLabel::Lost | AffectLabel::Frustrated | AffectLabel::Helpless
            ),
            "dread with an outlet is wariness, not distress: {felt:?}"
        );
        let memory = hazard_memory(&ledger, &test_folds(), &a, now, &terrain, &band);
        assert!(
            memory.dread.contains_key(&x),
            "fixture check: X really is a phantom, not a Haunt: {:?}",
            memory.dread
        );
        let danger = Danger {
            terrain: &terrain,
            threat_niche: a.threat_niche,
            boldness: a.boldness,
            alarm: None,
            dread: Some(&memory.dread),
        };
        assert!(
            matches!(
                danger.proposal(&view_at(x.clone()), PLAN_BUDGET),
                Some(Action::MoveTo(_))
            ),
            "it has somewhere to go — the dread is dischargeable"
        );

        // (3) DISPROVEN — the real tick. A steps off X (the discharge), and its
        // homeward walk carries it back onto the ground it feared, with no emitter
        // anywhere near: the most-recent verdict at X is SAFE, and the phantom
        // leaves BOTH halves of the memory.
        let folds = test_folds();
        let sys = DriveMovements {
            npcs: band.to_vec(),
            from: now,
            to: WorldTime::from_std_days(now.as_std_days() + 1.0).expect("a day value is finite"),
            params: SUSTENANCE,
            // No sky in a planted-terrain fixture: the action clock takes its
            // base rate (spec §4.1).
            day_ticks: None,
            terrain: &terrain,
            folds: &folds,
        };
        let next =
            hornvale_kernel::tick(&ledger, &[&sys], &["drive-movements"], &reg).expect("tick");
        let walked: Vec<Facet> = next
            .find(AGENT_AT)
            .filter(|f| f.subject == a_e)
            .filter(|f| f.day.map(|d| d >= now).unwrap_or(false))
            .filter_map(|f| match &f.object {
                Value::Text(s) => Some(room_from_text(s)),
                _ => None,
            })
            .collect();
        // The discharge, in the walk itself: the very first thing A does is leave
        // X. And the disproof is EARNED, not stipulated — the homeward pull brings
        // it back to stand on the feared ground while nothing is there to fear.
        // OFF X, not "onto p0 specifically". The old assertion named the
        // on-path predecessor because the triangular mesh left X with only one
        // safe direction to take; the cube-sphere mesh offers several, and
        // which one an equal-utility scan picks is an address tie-break, not
        // the claim. The claim is the discharge: it does not stand still.
        let first = walked.first().expect("the tick moves it somewhere");
        assert_ne!(
            first, &x,
            "the first step of the tick is OFF the haunted room: {walked:?}"
        );
        assert!(
            walked[1..].contains(&x),
            "and it comes back to stand there unharmed — the experience that \
             disproves the fear: {walked:?}"
        );
        let after = hazard_memory(
            &next,
            &test_folds(),
            &a,
            WorldTime::from_std_days(now.as_std_days() + 1.0).expect("a day value is finite"),
            &terrain,
            &band,
        );
        assert!(
            !after.dread.contains_key(&x),
            "standing there unharmed disproves the dread: {:?}",
            after.dread
        );
        assert!(
            !after.shunned.contains(&x),
            "and clears the shun with it — the phobia is falsifiable"
        );
    }

    /// A synthetic elevation + fresh-water field for pure tests: planted
    /// heights, INFINITY elsewhere (INFINITY = "never chosen downhill" —
    /// mirrors `LocaleTerrain`'s undescribable-room fallback), and a planted
    /// SET of fresh-water rooms (the-surmise T5 re-wire: water is no longer
    /// an elevation threshold — `Terrain::is_fresh_water` is authoritative).
    #[derive(Default)]
    pub(super) struct PlantedTerrain {
        elevations: std::collections::BTreeMap<Facet, f64>,
        fresh: std::collections::BTreeSet<Facet>,
        /// Planted per-room temperatures (°C) for the thermal-drive tests;
        /// INFINITY elsewhere (the thirst tests never read temperature).
        temps: std::collections::BTreeMap<Facet, f64>,
        /// Planted per-room food productivity for the hunger-drive tests;
        /// rooms without an entry read `DEFAULT_FORAGE` (fed) — so the thirst/
        /// thermal tests, which plant none, keep their creatures fed and
        /// hunger-inactive (byte-identical to pre-Provender behaviour).
        forage: std::collections::BTreeMap<Facet, f64>,
        /// Planted per-room hazards for the danger-drive tests; rooms without an
        /// entry read `Hazards::ZERO` (safe) — so the other tests, which plant
        /// none, are danger-inactive. Named `threat` for continuity; the
        /// `hazard()` constructor plants a scalar as the UNCANNY axis (the axis a
        /// mortal niche weights `1`, so the pre-Bane danger tests are byte-
        /// identical), and thermal tests plant `Hazards` directly.
        threat: std::collections::BTreeMap<Facet, Hazards>,
        /// Planted per-room prey presence (The Teeth's hunt tests); rooms without
        /// an entry read `0.0` (prey-empty) — so every other test is byte-
        /// identical (a carnivore there reads only ordinary productivity).
        prey: std::collections::BTreeMap<Facet, f64>,
    }
    impl PlantedTerrain {
        /// No elevation data — just a set of fresh-water rooms (the common
        /// case for the belief-fold tests, which never exercise
        /// `downhill_step`/`nearest_water`'s elevation reads).
        fn fresh_only(rooms: impl IntoIterator<Item = Facet>) -> Self {
            Self {
                fresh: rooms.into_iter().collect(),
                ..Default::default()
            }
        }
        /// No fresh water anywhere — just planted elevations (the
        /// exploration/downhill tests, which never exercise belief).
        fn dry(elevations: std::collections::BTreeMap<Facet, f64>) -> Self {
            Self {
                elevations,
                ..Default::default()
            }
        }
        /// Just planted per-room temperatures (the thermal-drive tests, which
        /// never exercise elevation/water). Rooms without a planted temperature
        /// read `INFINITY` (never chosen as a comfort target).
        fn thermal(temps: impl IntoIterator<Item = (Facet, f64)>) -> Self {
            Self {
                temps: temps.into_iter().collect(),
                ..Default::default()
            }
        }
        /// Just planted per-room food productivity (the hunger-drive tests).
        /// Rooms without an entry read `DEFAULT_FORAGE` (fed).
        fn forage(forage: impl IntoIterator<Item = (Facet, f64)>) -> Self {
            Self {
                forage: forage.into_iter().collect(),
                ..Default::default()
            }
        }
        /// Planted per-room fresh water AND a scalar hazard mapped to the UNCANNY
        /// axis (the danger-drive tests, which pair a hazard with a water source
        /// to prove routing). Rooms without an entry read `Hazards::ZERO` (safe).
        /// A mortal threat niche weights UNCANNY `1`, so a scalar `s` reads as
        /// felt threat `s` — the pre-Bane danger tests stay byte-identical.
        pub(super) fn hazard(
            fresh: impl IntoIterator<Item = Facet>,
            threat: impl IntoIterator<Item = (Facet, f64)>,
        ) -> Self {
            Self {
                fresh: fresh.into_iter().collect(),
                threat: threat
                    .into_iter()
                    .map(|(r, s)| {
                        (
                            r,
                            Hazards {
                                uncanny: s,
                                ..Hazards::ZERO
                            },
                        )
                    })
                    .collect(),
                ..Default::default()
            }
        }
        /// Planted per-room `Hazards` directly (the per-axis thermal-fear tests).
        fn hazards_map(hazards: impl IntoIterator<Item = (Facet, Hazards)>) -> Self {
            Self {
                threat: hazards.into_iter().collect(),
                ..Default::default()
            }
        }
        /// Planted per-room food productivity AND prey presence — the hunt tests
        /// (The Teeth): a carnivore on this ground reads productivity for its
        /// forage axis and the prey field for its prey axis. Rooms without a
        /// forage entry read `DEFAULT_FORAGE`; without a prey entry, `0.0`.
        fn forage_and_prey(
            forage: impl IntoIterator<Item = (Facet, f64)>,
            prey: impl IntoIterator<Item = (Facet, f64)>,
        ) -> Self {
            Self {
                forage: forage.into_iter().collect(),
                prey: prey.into_iter().collect(),
                ..Default::default()
            }
        }
    }

    /// The rooms the two end-to-end phantom fixtures share: a straight
    /// start→water path, an interior room `x` on it, an off-path room `d_room`
    /// beside `x` where the herd-mate panics, and the terrain hazard
    /// `hazard_e` beside `d_room` that gives it something to panic about.
    struct PhantomGeometry {
        /// The walker's home and the path's first room.
        start: Facet,
        /// The far end of the path, and the only fresh water.
        water: Facet,
        /// The interior path room the phantom attaches to. Terrain-SAFE.
        x: Facet,
        /// `x`'s on-path predecessor (one step from `start`).
        p0: Facet,
        /// `x`'s on-path successor.
        p2: Facet,
        /// The emitter's room: beside `x`, off the path, itself terrain-safe.
        d_room: Facet,
        /// The static hazard beside `d_room` — the ONLY planted hazard, and
        /// far enough from every path room that none of them is frightening.
        hazard_e: Facet,
    }

    /// [`PhantomGeometry`], built by asking for the properties the fixtures
    /// need rather than by taking the first neighbour that happened to have
    /// them.
    ///
    /// # What broke, and it is the same shape twice
    ///
    /// Both fixtures used to pick `hazard_e` as "the first neighbour of D that
    /// is not one of the five named rooms". On the triangular mesh that was
    /// enough, because a room two hops away could not also be one hop away.
    /// On the cube-sphere mesh a room has eight neighbours and the two-hop and
    /// one-hop sets overlap through the diagonals, so the chosen `hazard_e`
    /// sat BESIDE a path room — and `frightened_at` reads the neighbourhood,
    /// not just the room, so the path stopped being terrain-safe and the
    /// fixture's own guard said so:
    ///
    /// > `path room Facet { face: 0, path: [3, 0, 0, 0, 2, 0] } must be
    /// > terrain-safe (no static hazard)`
    ///
    /// The premise was never "the fourth-listed neighbour"; it was "a hazard
    /// whose fear reaches D and nothing else". So that is what this searches
    /// for — over both choices at once, since fixing only `hazard_e` would
    /// leave `d_room` picked by the same superseded rule. Deterministic (the
    /// mesh's own neighbour order, no draws) and loud: it panics with the
    /// reason rather than returning a pair that quietly makes every assertion
    /// below it vacuous.
    fn phantom_geometry() -> PhantomGeometry {
        let start = raddr(1.0);
        let mut water = start.clone();
        for _ in 0..4 {
            water = water
                .neighbors()
                .into_iter()
                .find(|n| *n != start)
                .expect("every room has a neighbour");
        }
        let empty = std::collections::BTreeSet::new();
        let straight = plan_to_room(&start, &water, PLAN_BUDGET, &empty).expect("reachable");
        assert!(straight.len() >= 4, "need a path with an interior room");
        let path_rooms: Vec<Facet> = straight
            .iter()
            .map(|a| match a {
                Action::MoveTo(r) => r.clone(),
                _ => unreachable!("plan_to_room emits only MoveTo"),
            })
            .collect();
        let x = path_rooms[1].clone();
        let p0 = path_rooms[0].clone();
        let p2 = path_rooms[2].clone();
        assert!(
            !start.neighbors().contains(&x) && !water.neighbors().contains(&x),
            "X must be interior (not adjacent to start or water)"
        );
        // The rooms a hazard must not touch: the whole walked path, ends
        // included. `frightened_at` reads a room AND its neighbours, so "not
        // touch" means neither equal to nor adjacent to any of them.
        let sacred: Vec<Facet> = vec![
            start.clone(),
            p0.clone(),
            x.clone(),
            p2.clone(),
            water.clone(),
        ];
        let clear_of_the_path = |r: &Facet| {
            let ns = r.neighbors();
            !sacred.iter().any(|s| s == r || ns.contains(s))
        };
        for d_room in x.neighbors() {
            if d_room == p0 || d_room == p2 || sacred.contains(&d_room) {
                continue;
            }
            // D must be adjacent to X (it is, by construction) and its own
            // hazard must reach D without reaching the path.
            if let Some(hazard_e) = d_room.neighbors().into_iter().find(clear_of_the_path) {
                return PhantomGeometry {
                    start,
                    water,
                    x,
                    p0,
                    p2,
                    d_room,
                    hazard_e,
                };
            }
        }
        panic!(
            "no off-path neighbour of X has a hazard neighbour clear of the whole \
             path — the phantom fixture cannot be built on this mesh, which is a \
             finding about the mesh rather than about these tests"
        );
    }

    /// The emitter's room, a terrain hazard beside it, and a halo room the
    /// hazard's own fear does NOT reach — the three rooms the unit-level
    /// phantom fixtures share.
    ///
    /// Six of them used to spell this as `ns[0]` for the hazard and `ns[1]`
    /// for the halo room, and on the triangular mesh that was sound: two
    /// neighbours of one room could not be neighbours of EACH OTHER. On the
    /// cube-sphere mesh they routinely are (any diagonal pair), so `ns[1]`
    /// began sitting inside `ns[0]`'s own one-hop fear halo — and
    /// `frightened_at` reads a room's NEIGHBOURS as well as the room, so the
    /// creature standing at X was primary-afraid of present terrain rather
    /// than remembering anything. Every "X is terrain-safe; the fear is
    /// memory, not sense" premise in this family died the same way, and each
    /// said so in its own words:
    ///
    /// > `X read terrain-only is safe`
    /// > `the shudderer must actually dread X`
    /// > `a creature with no memory of this ground feels nothing here`
    ///
    /// So the fixtures ask for the property. `d` is the emitter's room; `e` is
    /// a hazard beside `d`, so an emitter standing at `d` is primary-afraid;
    /// `x` is a room beside `d` (inside the emitter's one-hop alarm halo) that
    /// is neither `e` nor adjacent to it, so its own terrain frightens nobody.
    pub(super) fn phantom_triple() -> (Facet, Facet, Facet) {
        let d = raddr(1.0);
        let ns = d.neighbors();
        let hazard = ns[0].clone();
        let hazard_reach = hazard.neighbors();
        let x = ns
            .iter()
            .find(|n| **n != hazard && !hazard_reach.contains(n))
            .expect("D has a neighbour outside E's own one-hop reach")
            .clone();
        (d, hazard, x)
    }

    /// A water room a real walk away: two steps from `home`, through `via`.
    ///
    /// Three fixtures used to spell this as "`via`'s first neighbour that is
    /// not `home`", and on the triangular mesh that was the same thing — a
    /// room could not be both a neighbour of `home`'s neighbour and a
    /// neighbour of `home`. On the cube-sphere mesh the diagonals make it
    /// routine, and the room that clause picked turned out to sit on `home`'s
    /// own doorstep: the errand collapsed from four moves per thirst cycle to
    /// two, which is what took `the_hoisted_walk_emits_exactly_what_the_loop_
    /// emitted` from 80 facts to 56 and put a whole sleep between the arrival
    /// and the drink in `drinking_and_eating_now_cost_time`.
    ///
    /// The premise was always "the river is a walk away, not at the door", so
    /// that is what this asks for.
    fn water_beyond_the_doorstep(home: &Facet, via: &Facet) -> Facet {
        let doorstep = home.neighbors();
        via.neighbors()
            .into_iter()
            .find(|r| r != home && !doorstep.contains(r))
            .expect("a neighbour of `via` that is two steps from `home`")
    }

    /// `home` and EVERY one of its neighbours planted at `background`, with
    /// `exceptions` overriding by room — the shape a fixture that means "the
    /// whole room-scale neighbourhood reads X, except here" should ask for.
    ///
    /// # It replaces twenty hand-listed three-entry lists, and that is a
    /// finding rather than tidying
    ///
    /// Every caller below used to spell its background out as `(home, x),
    /// (ns[0], x), (ns[1], x), (ns[2], x)`, which WAS the whole neighbourhood
    /// while a room had three neighbours. A cube-sphere room has eight (seven
    /// at the 24 cube-corner rooms), so on The Pavement's mesh those lists
    /// stopped naming five of the rooms they meant, and the five fell through
    /// to [`PlantedTerrain`]'s UNPLANTED defaults — which are not neutral:
    ///
    /// - an unplanted TEMPERATURE reads `INFINITY`, which `Thermal::urgency_of`
    ///   maps to urgency `0.0`, so `MoveTo` there scores the maximum possible
    ///   thermal serviceability: a **perfect** destination;
    /// - an unplanted HAZARD reads `Hazards::ZERO`, so it is a **perfect**
    ///   refuge;
    /// - an unplanted FORAGE reads `DEFAULT_FORAGE` (fed), so it is **better**
    ///   than the barren ground the fixture planted.
    ///
    /// In all three the rooms the fixture forgot became the most attractive in
    /// the neighbourhood, which is why a dozen tests asserting "there is
    /// nowhere better to go" began reporting that there was — and why the
    /// winner in every one of those failures was the same room,
    /// `path: [0, 3, 3, 3, 3, 3]`: the ascending-address tie-break picking the
    /// first of the five unplanted rooms.
    ///
    /// Asking for the neighbourhood rather than listing it is what keeps the
    /// next mesh change from re-sending the same bill.
    fn neighbourhood_of<T: Clone>(
        home: &Facet,
        background: T,
        exceptions: impl IntoIterator<Item = (Facet, T)>,
    ) -> Vec<(Facet, T)> {
        let mut out: Vec<(Facet, T)> = std::iter::once(home.clone())
            .chain(home.neighbors())
            .map(|r| (r, background.clone()))
            .collect();
        // Appended AFTER the background, so a `BTreeMap` built by `collect`
        // takes the exception: a later insert of the same key wins.
        out.extend(exceptions);
        out
    }

    impl Terrain for PlantedTerrain {
        fn elevation(&self, room: &Facet) -> f64 {
            self.elevations.get(room).copied().unwrap_or(f64::INFINITY)
        }
        fn is_fresh_water(&self, room: &Facet) -> bool {
            self.fresh.contains(room)
        }
        fn temperature(&self, room: &Facet, _day: WorldTime) -> f64 {
            self.temps.get(room).copied().unwrap_or(f64::INFINITY)
        }
        fn forage_value(&self, room: &Facet) -> f64 {
            self.forage.get(room).copied().unwrap_or(DEFAULT_FORAGE)
        }
        fn hazards(&self, room: &Facet) -> Hazards {
            self.threat.get(room).copied().unwrap_or(Hazards::ZERO)
        }
        fn prey_value(&self, room: &Facet) -> f64 {
            self.prey.get(room).copied().unwrap_or(0.0)
        }
    }

    /// The default mortal threat niche (The Bane) — dreads the uncanny fully
    /// (weight `1`) and heat/cold at the level derived from
    /// [`DEFAULT_TEMPERATURE_NICHE`]. Used by
    /// tests that plant an UNCANNY hazard and expect the old scalar behaviour:
    /// `threat_value` reduces to the planted uncanny, so the pre-Bane danger
    /// tests stay byte-identical.
    fn mortal_threat_niche() -> ThreatNiche {
        derive_threat_niche(
            &DEFAULT_TEMPERATURE_NICHE,
            ThermalStrategy::Endothermic,
            &default_diet_niche(),
        )
    }

    /// A balanced omnivore diet (forage + prey) — the common hunger-test niche.
    fn omnivore_niche() -> ResourceVector {
        ResourceVector::new(&[(PLANT_FORAGE, 0.5), (ANIMAL_PREY, 0.5)]).unwrap()
    }

    #[test]
    fn food_value_is_the_niche_dotted_with_availability() {
        // An omnivore reads the room's material productivity (forage+prey);
        // a barren room feeds it less than a rich one.
        let rich = raddr(1.0);
        let barren = rich.neighbors()[0].clone();
        let t = PlantedTerrain::forage([(rich.clone(), 1.0), (barren.clone(), 0.0)]);
        let omni = omnivore_niche();
        let day = WorldTime::from_std_days(0.5).expect("a day value is finite"); // noon (sun up) — irrelevant to an omnivore
        assert!(
            food_value(&omni, &t, &rich, day)
                .total_cmp(&food_value(&omni, &t, &barren, day))
                .is_gt(),
            "richer ground is worth more food to an omnivore"
        );
        // An EMPTY niche reads no food anywhere (the niche-gate's basis).
        let empty = ResourceVector::new(&[]).unwrap();
        assert_eq!(food_value(&empty, &t, &rich, day), 0.0);
    }

    #[test]
    fn prey_ground_feeds_a_carnivore_and_leaves_a_herbivore_flat() {
        // THE TEETH: the prey field lifts `food_value` for the ANIMAL_PREY axis,
        // so prey-dense ground is worth more to a carnivore — but a pure
        // herbivore (no prey-axis weight) reads the prey field as nothing, so its
        // food_value is flat across prey-dense and prey-empty ground.
        let preyful = raddr(1.0);
        let empty = preyful.neighbors()[0].clone();
        // Uniform productivity, prey only on `preyful`.
        let t = PlantedTerrain::forage_and_prey(
            [(preyful.clone(), 1.0), (empty.clone(), 1.0)],
            [(preyful.clone(), 1.0)],
        );
        let day = WorldTime::from_std_days(0.5).expect("a day value is finite");
        let carnivore = ResourceVector::new(&[(ANIMAL_PREY, 1.0)]).unwrap();
        let herbivore = ResourceVector::new(&[(PLANT_FORAGE, 1.0)]).unwrap();
        assert!(
            food_value(&carnivore, &t, &preyful, day) > food_value(&carnivore, &t, &empty, day),
            "prey-dense ground feeds a carnivore more"
        );
        assert_eq!(
            food_value(&herbivore, &t, &preyful, day),
            food_value(&herbivore, &t, &empty, day),
            "a pure herbivore reads the prey field as nothing — flat"
        );
    }

    #[test]
    fn a_carnivore_forages_toward_prey_a_herbivore_does_not() {
        // THE TEETH, end to end: on ground of UNIFORM productivity (no forage
        // gradient) with prey concentrated in one neighbour, a carnivore forages
        // toward the prey — the hunt, live — while a herbivore, blind to the prey
        // field, follows only the (flat) forage and breaks the tie elsewhere.
        let c = raddr(1.0);
        let neighbors = c.neighbors();
        // The prey room is the LARGEST-address neighbour, so a herbivore's
        // uniform-forage tie-break (smallest address) can never land on it —
        // any pull toward it is the prey draw, not an artefact of the tie-break.
        let prey_room = neighbors.iter().max().unwrap().clone();
        let uniform: Vec<(Facet, f64)> = neighbors
            .iter()
            .cloned()
            .chain(std::iter::once(c.clone()))
            .map(|r| (r, 1.0))
            .collect();
        let t = PlantedTerrain::forage_and_prey(uniform, [(prey_room.clone(), 1.0)]);
        let day = WorldTime::from_std_days(0.5).expect("a day value is finite");
        let carnivore = ResourceVector::new(&[(ANIMAL_PREY, 1.0)]).unwrap();
        let herbivore = ResourceVector::new(&[(PLANT_FORAGE, 1.0)]).unwrap();
        assert_eq!(
            forage_step(&c, &carnivore, &t, day),
            Some(prey_room.clone()),
            "a carnivore forages toward prey-dense ground"
        );
        assert_ne!(
            forage_step(&c, &herbivore, &t, day),
            Some(prey_room),
            "a herbivore ignores the prey field (uniform forage → tie-break, not prey)"
        );
    }

    #[test]
    fn an_autotroph_is_fed_by_light_not_forage() {
        // A pure photosynthate niche reads the SUN, not the productivity field:
        // fed by day (sun up), starved at night — even on barren ground.
        let room = raddr(1.0);
        let t = PlantedTerrain::forage([(room.clone(), 0.0)]); // no material food
        let autotroph = ResourceVector::new(&[(PHOTOSYNTHATE, 1.0)]).unwrap();
        let noon = WorldTime::from_std_days(0.5).expect("a day value is finite"); // fractional_day_sun → +90°
        let midnight = WorldTime::GENESIS; // → −90°
        assert!(
            food_value(&autotroph, &t, &room, noon) > 0.0,
            "an autotroph eats by day"
        );
        assert_eq!(
            food_value(&autotroph, &t, &room, midnight),
            0.0,
            "an autotroph starves at night"
        );
    }

    #[test]
    fn hunger_folds_eaten_and_resets_on_a_meal() {
        // HUNGER == FOLD over `eaten`, the twin of thirst over `drank`.
        let reg = {
            let mut r = agent_at_reg();
            r.register_predicate(EATEN, false, "eaten").unwrap();
            r
        };
        let home = raddr(1.0);
        let mut ledger = Ledger::default();
        let e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
        // No meal yet → hunger has risen by day 5 (a thermoneutral/unreadable
        // room couples at the base HUNGER rate).
        let t = PlantedTerrain::forage(std::iter::empty());
        let before = hunger_at(
            &ledger,
            &test_folds(),
            e,
            &home,
            WorldTime::from_std_days(5.0).expect("a day value is finite"),
            &t,
            ThermalStrategy::Endothermic,
        );
        assert!(before > 0.0, "hunger accrues without a meal");
        // Eat on day 5 → hunger is 0 right after.
        ledger.commit(eaten_fact(e, td(5.0), "ate"), &reg).unwrap();
        let after = hunger_at(
            &ledger,
            &test_folds(),
            e,
            &home,
            WorldTime::from_std_days(5.0).expect("a day value is finite"),
            &t,
            ThermalStrategy::Endothermic,
        );
        assert_eq!(after, 0.0, "a meal resets hunger");
    }

    #[test]
    fn hunger_proposal_eats_at_a_rich_cell_and_forages_from_a_barren_one() {
        let barren = raddr(1.0);
        // Plant EVERY neighbour barren except one, so the forage step is
        // unambiguous (unplanted rooms default to DEFAULT_FORAGE, which would
        // otherwise tie).
        let ns = barren.neighbors();
        let rich = ns[0].clone();
        let t = PlantedTerrain::forage(neighbourhood_of(&barren, 0.0, [(rich.clone(), 1.0)]));
        let day = WorldTime::GENESIS;
        let view_barren = Perceived {
            position: barren.clone(),
            drive: 0.0,
            fatigue: 0.0,
            believed_water: None,
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: None,
        };
        let hunger = Hunger {
            urgency: 0.9,
            niche: omnivore_niche(),
            terrain: &t,
            day,
        };
        // Barren room: forage toward the richer neighbour.
        assert_eq!(
            hunger.proposal(&view_barren, PLAN_BUDGET),
            Some(Action::MoveTo(rich.clone())),
            "a hungry creature on barren ground forages toward richer ground"
        );
        // Rich room: eat in place.
        let view_rich = Perceived {
            position: rich.clone(),
            drive: 0.0,
            fatigue: 0.0,
            believed_water: None,
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: None,
        };
        assert_eq!(
            hunger.proposal(&view_rich, PLAN_BUDGET),
            Some(Action::Eat),
            "a hungry creature on rich ground eats in place"
        );
    }

    #[test]
    fn hunger_integrates_faster_over_a_hot_occupancy() {
        // The Kindling coupling, reused: a hot endotherm hungers faster than a
        // thermoneutral one over the same elapsed time (mirrors the thirst test).
        let home = raddr(1.0);
        let hot = PlantedTerrain::thermal([(home.clone(), 45.0)]);
        let mild = PlantedTerrain::thermal([(home.clone(), 25.0)]);
        let mut ledger = Ledger::default(); // no eaten, no sightings → held at home
        let e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
        let day = WorldTime::from_std_days(3.0).expect("a day value is finite");
        let hot_h = hunger_at(
            &ledger,
            &test_folds(),
            e,
            &home,
            day,
            &hot,
            ThermalStrategy::Endothermic,
        );
        let mild_h = hunger_at(
            &ledger,
            &test_folds(),
            e,
            &home,
            day,
            &mild,
            ThermalStrategy::Endothermic,
        );
        assert!(
            hot_h.total_cmp(&mild_h).is_gt(),
            "heat hastens hunger for an endotherm"
        );
    }

    /// A `Perceived` view standing at `pos`, with the non-danger drives quiet
    /// (danger reads only `position` + the terrain it holds).
    fn view_at(pos: Facet) -> Perceived {
        Perceived {
            position: pos,
            drive: 0.0,
            fatigue: 0.0,
            believed_water: None,
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: None,
        }
    }

    #[test]
    fn danger_urgency_reads_the_cell_threat_and_defaults_safe() {
        let scary = raddr(1.0);
        // A room on the far side of the world — neither it nor its neighbours
        // touch the threat, so anticipatory urgency reads 0.
        let far = raddr(-1.0);
        let t = PlantedTerrain::hazard(std::iter::empty(), [(scary.clone(), 0.8)]);
        let danger = Danger {
            terrain: &t,
            threat_niche: mortal_threat_niche(),
            boldness: BOLDNESS_STEADY,
            alarm: None,
            dread: None,
        };
        assert_eq!(
            danger.urgency(&view_at(scary)),
            0.8,
            "feels the room's threat"
        );
        assert_eq!(
            danger.urgency(&view_at(far)),
            0.0,
            "a room far from any threat is safe"
        );
    }

    #[test]
    fn danger_urgency_reads_remembered_dread_on_now_safe_ground() {
        // THE SHUDDER: a room with NO hazard anywhere near it — present threat 0 —
        // frightens a creature that remembers a herd's alarm there. Fear of
        // nothing present. `None` dread on the same room reads calm, so the term
        // is additive-latent: byte-identical wherever the map is empty.
        let safe = raddr(-1.0); // neither it nor its neighbours carry any hazard
        let t = PlantedTerrain::hazard(std::iter::empty(), std::iter::empty());
        let mut dread = std::collections::BTreeMap::new();
        dread.insert(safe.clone(), 0.8);

        let calm = Danger {
            terrain: &t,
            threat_niche: mortal_threat_niche(),
            boldness: BOLDNESS_STEADY,
            alarm: None,
            dread: None,
        };
        assert_eq!(
            calm.urgency(&view_at(safe.clone())),
            0.0,
            "without the memory the ground is unremarkable"
        );

        let haunted = Danger {
            terrain: &t,
            threat_niche: mortal_threat_niche(),
            boldness: BOLDNESS_STEADY,
            alarm: None,
            dread: Some(&dread),
        };
        let felt = haunted.urgency(&view_at(safe));
        assert_eq!(
            felt, 0.8,
            "the remembered alarm is felt as the alarm it was"
        );
        assert!(felt >= DANGER_ACT, "and it crosses act — the drive engages");
    }

    #[test]
    fn danger_discharges_dread_by_stepping_off_the_haunted_cell() {
        // THE AFFORDANCE (spec §2, ledger #1). A phantom room is now-SAFE ground,
        // so terrain offers no gradient to flee down: without a dread-aware
        // serviceability the creature would Hold and read `Lost` — a distress
        // tick for a feature that is a feeling, not a pathology. With it, every
        // neighbour is an improvement and the creature steps off.
        let here = raddr(-1.0);
        let t = PlantedTerrain::hazard(std::iter::empty(), std::iter::empty());
        let mut dread = std::collections::BTreeMap::new();
        dread.insert(here.clone(), 0.8);
        let danger = Danger {
            terrain: &t,
            threat_niche: mortal_threat_niche(),
            boldness: BOLDNESS_STEADY,
            alarm: None,
            dread: Some(&dread),
        };
        let view = view_at(here.clone());
        let step = danger
            .proposal(&view, PLAN_BUDGET)
            .expect("dread on flat ground still offers a step off it");
        let Action::MoveTo(to) = step else {
            panic!("fleeing is a MoveTo");
        };
        assert!(here.neighbors().contains(&to), "it steps to a neighbour");
        assert!(
            danger.serviceability(&Action::MoveTo(to), &view, PLAN_BUDGET, &mut || None) > 0.0,
            "stepping off the dreaded room positively serves the drive"
        );
    }

    #[test]
    fn danger_without_dread_is_unchanged_on_flat_ground() {
        // The byte-identity half of the same seam: `dread: None` on hazard-free
        // ground still offers NO flee step (nowhere is strictly safer) — today's
        // behaviour exactly.
        let here = raddr(-1.0);
        let t = PlantedTerrain::hazard(std::iter::empty(), std::iter::empty());
        let danger = Danger {
            terrain: &t,
            threat_niche: mortal_threat_niche(),
            boldness: BOLDNESS_STEADY,
            alarm: None,
            dread: None,
        };
        assert_eq!(danger.proposal(&view_at(here), PLAN_BUDGET), None);
    }

    #[test]
    fn flee_step_picks_the_safest_neighbour_or_none_when_cornered() {
        let here = raddr(1.0);
        let ns = here.neighbors();
        // here is dangerous; one neighbour is safe(r), the others as bad as here.
        let t = PlantedTerrain::hazard(
            std::iter::empty(),
            neighbourhood_of(&here, 0.9, [(ns[0].clone(), 0.1)]),
        );
        let danger = Danger {
            terrain: &t,
            threat_niche: mortal_threat_niche(),
            boldness: BOLDNESS_STEADY,
            alarm: None,
            dread: None,
        };
        assert_eq!(
            danger.proposal(&view_at(here.clone()), PLAN_BUDGET),
            Some(Action::MoveTo(ns[0].clone())),
            "flees to the safest neighbour"
        );
        // Cornered: here and every neighbour equally dangerous → no safer step.
        let boxed = PlantedTerrain::hazard(
            std::iter::empty(),
            here.neighbors()
                .into_iter()
                .chain(std::iter::once(here.clone()))
                .map(|r| (r, 0.9)),
        );
        let danger_boxed = Danger {
            terrain: &boxed,
            threat_niche: mortal_threat_niche(),
            boldness: BOLDNESS_STEADY,
            alarm: None,
            dread: None,
        };
        assert_eq!(
            danger_boxed.proposal(&view_at(here), PLAN_BUDGET),
            None,
            "boxed in by threat everywhere → holds (cornered)"
        );
    }

    #[test]
    fn danger_serviceability_is_signed_penalising_a_step_into_worse_danger() {
        let here = raddr(1.0);
        let ns = here.neighbors();
        let safer = ns[0].clone();
        let worse = ns[1].clone();
        let t = PlantedTerrain::hazard(
            std::iter::empty(),
            [
                (here.clone(), 0.5),
                (safer.clone(), 0.1),
                (worse.clone(), 0.9),
            ],
        );
        let danger = Danger {
            terrain: &t,
            threat_niche: mortal_threat_niche(),
            boldness: BOLDNESS_STEADY,
            alarm: None,
            dread: None,
        };
        let view = view_at(here);
        // Toward safety: positive (0.5 − 0.1).
        assert!(
            danger.serviceability(&Action::MoveTo(safer), &view, PLAN_BUDGET, &mut || None) > 0.0,
            "a step toward safety is served"
        );
        // Into worse danger: NEGATIVE (0.5 − 0.9) — the unclamped modulation.
        assert!(
            danger.serviceability(&Action::MoveTo(worse), &view, PLAN_BUDGET, &mut || None) < 0.0,
            "a step into worse danger is penalised (signed serviceability)"
        );
    }

    #[test]
    fn danger_routes_a_thirsty_creature_around_a_hazard_to_water() {
        // THE KEYSTONE (the potential-field modulation): water lies past a
        // dangerous room; a safe detour neighbour exists. The creature, though
        // thirsty and knowing the water, does NOT step onto the hazard — danger's
        // negative serviceability outweighs thirst's pull on that move.
        let home = raddr(1.0);
        let ns = home.neighbors();
        let hazard = ns[0].clone(); // the direct step toward water, but deadly
        let detour = ns[1].clone(); // a safe alternative step
        let water = hazard.clone(); // believed water sits on/at the hazard room
        let t = PlantedTerrain::hazard([water.clone()], [(hazard.clone(), 1.0)]);
        let danger = Danger {
            terrain: &t,
            threat_niche: mortal_threat_niche(),
            boldness: BOLDNESS_STEADY,
            alarm: None,
            dread: None,
        };
        let thirst = Thirst { params: SUSTENANCE };
        let view = Perceived {
            position: home.clone(),
            drive: 0.9, // very thirsty
            fatigue: 0.0,
            believed_water: Some(water.clone()),
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: Some(detour.clone()),
        };
        let drives: [&dyn Drive; 2] = [&thirst, &danger];
        let res = arb(
            &view,
            &home,
            &drives,
            1.0, // weigh (both drives counted)
            0.0,
            false,
            true,
            Mode::Idle,
            PLAN_BUDGET,
        );
        // Whatever it does, it must NOT step onto the deadly hazard room.
        assert_ne!(
            res.intent,
            Intent::Do(Action::MoveTo(hazard.clone())),
            "a thirsty creature refuses to cross a lethal hazard even toward water"
        );
    }

    #[test]
    fn danger_urgency_is_clamped_and_a_flow_drive_carries_no_state() {
        // A flow drive: urgency is purely the room field, no fold, clamped [0,1].
        let room = raddr(1.0);
        let t = PlantedTerrain::hazard(std::iter::empty(), [(room.clone(), 1.5)]);
        let danger = Danger {
            terrain: &t,
            threat_niche: mortal_threat_niche(),
            boldness: BOLDNESS_STEADY,
            alarm: None,
            dread: None,
        };
        assert_eq!(
            danger.urgency(&view_at(room)),
            1.0,
            "threat urgency clamps at 1.0"
        );
    }

    #[test]
    fn boldness_scales_the_felt_threat_across_the_mettle_axis() {
        // THE METTLE: `effective = base × 2(1 − boldness)`, centered on 0.5.
        let room = raddr(1.0);
        let t = PlantedTerrain::hazard(std::iter::empty(), [(room.clone(), 0.4)]);
        let v = view_at(room);
        let feel = |boldness: f64| {
            Danger {
                terrain: &t,
                threat_niche: mortal_threat_niche(),
                boldness,
                alarm: None,
                dread: None,
            }
            .urgency(&v)
        };
        // Steady (0.5) → ×1 (unchanged, the inert baseline).
        assert_eq!(feel(0.5), 0.4, "steady feels the threat as it is");
        // Bold (0.8) → ×0.4.
        assert!(
            (feel(0.8) - 0.4 * 0.4).abs() < 1e-9,
            "a bold creature fears less"
        );
        // Fearless (1.0) → ×0.
        assert_eq!(feel(1.0), 0.0, "the fearless feel nothing");
        // Coward (0.0) → ×2, clamped at 1.0.
        assert_eq!(
            feel(0.0),
            (0.4_f64 * 2.0).min(1.0),
            "a coward fears more (clamped)"
        );
        // The monotone axis: coward > steady > bold > fearless.
        assert!(feel(0.0) > feel(0.5) && feel(0.5) > feel(0.8) && feel(0.8) > feel(1.0));
    }

    #[test]
    fn alarm_raises_a_calm_creatures_danger() {
        // THE ALARM: a creature on hazard-free ground feels nothing of its own,
        // but a borrowed alarm at its room wakes its Danger drive additively.
        let room = raddr(1.0);
        let t = PlantedTerrain::default(); // no hazard anywhere — nothing to fear
        let mut map: std::collections::BTreeMap<Facet, f64> = std::collections::BTreeMap::new();
        map.insert(room.clone(), 0.8);
        let feel = |alarm: Option<&std::collections::BTreeMap<Facet, f64>>| {
            Danger {
                terrain: &t,
                threat_niche: mortal_threat_niche(),
                boldness: BOLDNESS_STEADY,
                alarm,
                dread: None,
            }
            .urgency(&view_at(room.clone()))
        };
        let felt = feel(Some(&map));
        assert!(felt > 0.0, "borrowed alarm raises felt threat above zero");
        assert!(
            felt >= DANGER_ACT,
            "a full-strength alarm crosses the danger act threshold"
        );
        assert_eq!(
            feel(None),
            0.0,
            "with no alarm field a calm creature on safe ground fears nothing"
        );
    }

    #[test]
    fn borrowed_alarm_is_scaled_by_boldness() {
        // THE ALARM reuses THE METTLE's dial: borrowed fear is scaled by the
        // reader's own `mettle_factor`, so a bold creature shrugs off the herd's
        // panic exactly as it shrugs off a hazard.
        let room = raddr(1.0);
        let t = PlantedTerrain::default();
        let mut map: std::collections::BTreeMap<Facet, f64> = std::collections::BTreeMap::new();
        map.insert(room.clone(), 0.8);
        let feel = |boldness: f64| {
            Danger {
                terrain: &t,
                threat_niche: mortal_threat_niche(),
                boldness,
                alarm: Some(&map),
                dread: None,
            }
            .urgency(&view_at(room.clone()))
        };
        // Bold < steady < coward — the monotone Mettle ordering, borrowed.
        assert!(
            feel(0.9) < feel(0.5) && feel(0.5) < feel(0.1),
            "a bold creature feels less of the borrowed alarm than a coward"
        );
        // A bold omnivore shrugs the herd off — its borrowed alarm stays below act.
        assert!(
            feel(0.9) < DANGER_ACT,
            "a bold creature's borrowed alarm falls below the danger act threshold"
        );
    }

    #[test]
    fn alarm_is_additive_over_terrain_hazard() {
        // THE ALARM is ADDITIVE: on mildly hazardous ground the borrowed alarm
        // stacks on the creature's own felt threat, strictly above either alone.
        let room = raddr(1.0);
        let t = PlantedTerrain::hazard(std::iter::empty(), [(room.clone(), 0.2)]);
        let mut map: std::collections::BTreeMap<Facet, f64> = std::collections::BTreeMap::new();
        map.insert(room.clone(), 0.5);
        let both = Danger {
            terrain: &t,
            threat_niche: mortal_threat_niche(),
            boldness: BOLDNESS_STEADY,
            alarm: Some(&map),
            dread: None,
        }
        .urgency(&view_at(room.clone()));
        let terrain_only = Danger {
            terrain: &t,
            threat_niche: mortal_threat_niche(),
            boldness: BOLDNESS_STEADY,
            alarm: None,
            dread: None,
        }
        .urgency(&view_at(room.clone()));
        // With ALARM_SCALE = 1.0 and steady boldness: 0.2 + 0.5 = 0.7.
        assert!(
            (both - 0.7).abs() < 1e-9,
            "felt threat is base + ALARM_SCALE * alarm"
        );
        assert!(
            both > terrain_only && both > 0.5,
            "the sum is strictly above either the terrain hazard or the alarm alone"
        );
    }

    /// A steady mortal NPC placed (via `commit_agent_at`) at `pos`, minted into
    /// `ledger` — the common emitter/reader for the `alarm_field` tests.
    /// `boldness` dials whether it is primary-afraid on hazard ground.
    fn alarm_npc(ledger: &mut Ledger, reg: &ConceptRegistry, pos: &Facet, boldness: f64) -> Body {
        let e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
        commit_agent_at(ledger, reg, e, pos, 0.0);
        Body {
            entity: e,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home: pos.clone(),
            resource: pos.clone(),
            species: "goblin".into(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Endothermic,
            niche: default_diet_niche(),
            boldness,
            threat_niche: mortal_threat_niche(),
            // The action clock's reference mass (The Action Clock T2): tempo is
            // exactly `1.0` here, so this fixture's timings are unmoved.
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: "creature".into(),
        }
    }

    #[test]
    fn alarm_field_is_empty_with_no_primary_fear() {
        // THE ALARM: a settled population on hazard-free ground raises no alarm —
        // the field is empty, the byte-identical resting state.
        let reg = agent_at_reg();
        let mut ledger = Ledger::default();
        let a = raddr(1.0);
        let b = a.neighbors()[0].clone();
        let npc_a = alarm_npc(&mut ledger, &reg, &a, BOLDNESS_STEADY);
        let npc_b = alarm_npc(&mut ledger, &reg, &b, BOLDNESS_STEADY);
        let terrain = PlantedTerrain::default(); // no hazard anywhere
        let field = alarm_field(
            &ledger,
            &test_folds(),
            &[npc_a, npc_b],
            &terrain,
            WorldTime::from_std_days(0.5).expect("a day value is finite"),
        );
        assert!(
            field.is_empty(),
            "no creature is primary-afraid, so the alarm field is empty: {field:?}"
        );
    }

    #[test]
    fn alarm_field_haloes_a_primary_afraid_creature() {
        // THE ALARM: one creature on an UNCANNY-hazard room (its Danger crosses
        // act) stamps a one-hop halo — its room and its neighbours carry
        // alarm in [0, 1]; a distant room is untouched.
        let reg = agent_at_reg();
        let mut ledger = Ledger::default();
        let room = raddr(1.0);
        let ns = room.neighbors();
        let far = raddr(-1.0); // the far side of the world, outside the halo
        let npc = alarm_npc(&mut ledger, &reg, &room, BOLDNESS_STEADY);
        // A full-strength uncanny hazard ONLY on the creature's room.
        let terrain = PlantedTerrain::hazard(std::iter::empty(), [(room.clone(), 0.8)]);
        let field = alarm_field(
            &ledger,
            &test_folds(),
            &[npc],
            &terrain,
            WorldTime::from_std_days(0.5).expect("a day value is finite"),
        );
        for room in std::iter::once(&room).chain(ns.iter()) {
            let v = field.get(room).copied().unwrap_or(0.0);
            assert!(
                v > 0.0 && v <= 1.0,
                "the halo room {room:?} carries alarm in (0, 1]: {v}"
            );
        }
        assert!(
            !field.contains_key(&far),
            "a room far from the distress carries no alarm"
        );
    }

    #[test]
    fn alarm_field_does_not_re_emit() {
        // THE ALARM's termination guarantee (built alarm-free): a creature A on
        // genuine hazard ground is primary-afraid and emits; a BOLD creature B on
        // an adjacent room shrugs the hazard off (its own terrain danger is below
        // act) and so contributes NOTHING — borrowed alarm is never re-emitted.
        let reg = agent_at_reg();
        let mut ledger = Ledger::default();
        let h = raddr(1.0); // A's hazard room
        let ns = h.neighbors();
        let b_room = ns[0].clone(); // B sits one hop from A, inside A's halo
        // A is a coward (feels the hazard fully); B is bold (shrugs it off).
        let a = alarm_npc(&mut ledger, &reg, &h, BOLDNESS_STEADY);
        let b = alarm_npc(&mut ledger, &reg, &b_room, 0.95);
        let terrain = PlantedTerrain::hazard(std::iter::empty(), [(h.clone(), 0.8)]);
        // The field over BOTH creatures.
        let both = alarm_field(
            &ledger,
            &test_folds(),
            &[a.clone(), b.clone()],
            &terrain,
            WorldTime::from_std_days(0.5).expect("a day value is finite"),
        );
        // The field over A ALONE — the reference: B must add nothing.
        let a_only = alarm_field(
            &ledger,
            &test_folds(),
            &[a],
            &terrain,
            WorldTime::from_std_days(0.5).expect("a day value is finite"),
        );
        assert_eq!(
            both, a_only,
            "the bold neighbour B is not primary-afraid, so it re-emits no alarm"
        );
        // And B's own neighbours OUTSIDE A's halo are untouched — no secondary wave.
        for n in b_room.neighbors() {
            if n != h && !ns.contains(&n) {
                assert!(
                    !both.contains_key(&n),
                    "B does not stamp its own halo: {n:?} must be absent"
                );
            }
        }
    }

    #[test]
    fn the_herd_bolts_borrowed_alarm_makes_a_calm_creature_flee_then_settle() {
        // THE ALARM, end-to-end (the spec's e2e criterion): drive the REAL
        // field-aware `DriveMovements` tick, not a hand-built affect. Creature A
        // is CORNERED on genuine UNCANNY hazard ground (its room and every
        // neighbour are hazardous, so no step is strictly safer — it holds, and
        // keeps screaming every tick). Creature B stands one hop away, INSIDE
        // A's alarm halo, but dreads the uncanny only WEAKLY (a low threat-niche
        // weight), so its OWN terrain-sourced danger stays below `act`: B has NO
        // primary fear of its own. Yet the BORROWED alarm at B's room pushes it
        // over `act`, and B flees down the local threat gradient to safe ground
        // OUTSIDE the halo — then, separated from the distress, it settles. The
        // wave is bounded and terminates (spec §3): no perpetual stampede.

        // A registry carrying every predicate the tick may commit.
        let mut reg = ConceptRegistry::default();
        reg.register_predicate(AGENT_AT, false, "pos").unwrap();
        reg.register_predicate(DRANK, false, "drank").unwrap();
        reg.register_predicate(RESTED, false, "rested").unwrap();
        reg.register_predicate(SLEPT, false, "slept").unwrap();
        reg.register_predicate(EATEN, false, "eaten").unwrap();
        for (key, doc) in errand_predicates() {
            reg.register_predicate(key, false, doc).unwrap();
        }

        // Geometry, read from the real mesh so the scenario is topology-robust.
        let x = raddr(1.0); // A's room — the core of the hazard
        let ns = x.neighbors(); // A's neighbours
        let b_start = ns[0].clone(); // B stands here: one hop from A, in the halo
        // The hazard patch = A's room AND its neighbours, so A is boxed in (no
        // neighbour is strictly safer → cornered, holds, keeps emitting).
        let patch: std::collections::BTreeSet<Facet> = std::iter::once(x.clone())
            .chain(ns.iter().cloned())
            .collect();
        // B's escape: a neighbour of B's room OUTSIDE the patch — and thus
        // outside A's one-hop halo. The mesh gives B such a way out; assert it.
        let escape: std::collections::BTreeSet<Facet> = b_start
            .neighbors()
            .into_iter()
            .filter(|n| !patch.contains(n))
            .collect();
        assert!(
            !escape.is_empty(),
            "B must have a hop out of the halo for the wave to terminate"
        );
        // `flee_step` (and arbitration) pick the safest neighbour, ties to the
        // smallest Facet — among the equally-safe escape rooms that is the
        // minimum. Make it B's home, so B flees home to safety and rests there
        // (no home-ward pull back into the halo → no oscillation).
        let b_home = escape.iter().min().unwrap().clone();

        // A strong UNCANNY hazard over the whole patch.
        let terrain =
            PlantedTerrain::hazard(std::iter::empty(), patch.iter().cloned().map(|c| (c, 0.8)));

        // A — a mortal dreading the uncanny fully (weight 1), steady boldness:
        // felt threat 0.8 ≥ DANGER_ACT, cornered, emits arousal 0.8 every tick.
        let build_a = |ledger: &mut Ledger| -> Body {
            let e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
            commit_agent_at(ledger, &reg, e, &x, 0.0);
            Body {
                entity: e,
                village: None,
                perception: hornvale_species::PerceptionVector::MANIKIN,
                home: x.clone(),
                resource: x.clone(),
                species: "goblin".into(),
                activity: hornvale_species::ActivityCycle::Diurnal,
                temperature_niche: test_niche(),
                deliberation_latency: 0.5,
                time_horizon: 0.0,
                thermal_strategy: ThermalStrategy::Endothermic,
                niche: default_diet_niche(),
                boldness: BOLDNESS_STEADY,
                threat_niche: mortal_threat_niche(),
                // The action clock's reference mass (The Action Clock T2): tempo is
                // exactly `1.0` here, so this fixture's timings are unmoved.
                mass_kg: crate::clock::REFERENCE_MASS_KG,
                label: "cornered".into(),
            }
        };
        // B — dreads the uncanny only WEAKLY (0.25), so 0.8·0.25 = 0.20 <
        // DANGER_ACT (0.3): NO primary fear of its own. Its home is the safe
        // escape room it flees to.
        let build_b = |ledger: &mut Ledger| -> Body {
            let e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
            commit_agent_at(ledger, &reg, e, &b_start, 0.0);
            Body {
                entity: e,
                village: None,
                perception: hornvale_species::PerceptionVector::MANIKIN,
                home: b_home.clone(),
                resource: b_home.clone(),
                species: "goblin".into(),
                activity: hornvale_species::ActivityCycle::Diurnal,
                temperature_niche: test_niche(),
                deliberation_latency: 0.5,
                time_horizon: 0.0,
                thermal_strategy: ThermalStrategy::Endothermic,
                niche: default_diet_niche(),
                boldness: BOLDNESS_STEADY,
                threat_niche: ThreatNiche {
                    uncanny: 0.25,
                    heat: 0.0,
                    cold: 0.0,
                    predator: 0.0,
                },
                // The action clock's reference mass (The Action Clock T2): tempo is
                // exactly `1.0` here, so this fixture's timings are unmoved.
                mass_kg: crate::clock::REFERENCE_MASS_KG,
                label: "herd-edge".into(),
            }
        };

        // --- The contagion run: A present and cornered, B one hop away. ---
        let mut ledger = Ledger::default();
        let a = build_a(&mut ledger);
        let b = build_b(&mut ledger);
        let a_entity = a.entity;
        let b_entity = b.entity;

        // THE WINDOW IS SIZED FROM THE CLOCK, NOT WRITTEN DOWN. It used to be a
        // flat `0.30 → 0.40` — 0.10 days, exactly one `MoveTo` at the reference
        // mass — and that stopped admitting B's flight the moment steps became
        // octile (The Pavement, Task 7): B's escape happens to be a DIAGONAL,
        // which costs 17/12 of an orthogonal, so a window sized to one
        // orthogonal admitted NO action at all. The tick then emitted zero
        // facts and the failure read `B ... FLEES the borrowed alarm`, which
        // points at the contagion rather than at the clock — a fixture premise
        // failing in the language of the claim it was supposed to support.
        //
        // 1.2 flights: one step fits, a second cannot (0.2 of a flight is left,
        // and the cheapest move is a whole orthogonal). Both ticks take the
        // same length so the "settles" half is not quietly given a shorter
        // window than the "bolts" half.
        let flight = crate::clock::cost_of(
            &Action::MoveTo(b_home.clone()),
            crate::clock::REFERENCE_MASS_KG,
            1.0,
            crate::clock::step_factor(&b_start, &b_home),
        )
        .as_std_days();
        let t0 = 0.30;
        let t1 = t0 + 1.2 * flight;
        let t2 = t1 + 1.2 * flight;

        // TICK 1 — the daytime window (both awake). The alarm field haloes A's
        // neighbourhood (B's room included), so B bolts.
        let folds = test_folds();
        let sys1 = DriveMovements {
            npcs: vec![a.clone(), b.clone()],
            from: WorldTime::from_std_days(t0).expect("a day value is finite"),
            to: WorldTime::from_std_days(t1).expect("a day value is finite"),
            params: SUSTENANCE,
            // No sky in a planted-terrain fixture: the action clock takes its
            // base rate (spec §4.1).
            day_ticks: None,
            terrain: &terrain,
            folds: &folds,
        };
        let after1 = hornvale_kernel::tick(&ledger, &[&sys1], &["drive-movements"], &reg).unwrap();

        // B's actual tick STEPS (excluding the day-0 seed placement).
        let b_moves_1: Vec<&Fact> = after1
            .find(AGENT_AT)
            .filter(|f| f.subject == b_entity && f.provenance != "test")
            .collect();
        // KEYED ON THE ERRAND PREDICATE, NOT ON PROVENANCE TEXT (The Warrant,
        // Task 3). This read used to be `f.provenance.contains("fear")` over
        // the `agent-at` facts above. Every step's provenance is
        // `vessel/liveness` now, so that substring search would match nothing
        // and this assertion would fail honestly — but its CONTROL twin at
        // the bottom of this test (`c_fear == 0`) would have gone on passing
        // for exactly the wrong reason, which is the more dangerous half.
        // Both are re-pointed at [`ERRAND_FLIGHT`], the permanent on-disk key
        // for the same drive.
        let b_fear_moves = after1
            .find(ERRAND_FLIGHT)
            .filter(|f| f.subject == b_entity)
            .count();
        assert!(
            b_fear_moves >= 1,
            "B, with no primary fear of its own, FLEES the borrowed alarm (an {ERRAND_FLIGHT} errand)"
        );
        // Bounded — no perpetual within-tick stampede (the field is fixed across
        // the interval; an oscillating B would run to MAX_STEPS, committing
        // thousands of moves). A small count proves the wave is a bounded halo.
        assert!(
            b_moves_1.len() <= 4,
            "B's flight is bounded, not a runaway stampede: got {} moves",
            b_moves_1.len()
        );
        // A is cornered — it never STEPS during the tick (only the day-0 seed
        // placement, provenance "test", is on the ledger). It holds and keeps
        // emitting, the persistent alarm source.
        assert_eq!(
            after1
                .find(AGENT_AT)
                .filter(|f| f.subject == a_entity && f.provenance != "test")
                .count(),
            0,
            "the cornered A holds its ground, the persistent alarm source"
        );

        // TICK 2 — A still cornered and screaming; B now on safe ground OUTSIDE
        // the halo. The alarm no longer reaches B, so it settles: no new move.
        // TERMINATION (spec §3): the wave dies not because the source vanished
        // (A still screams) but because B escaped the one-hop halo.
        let folds = test_folds();
        let sys2 = DriveMovements {
            npcs: vec![a.clone(), b.clone()],
            from: WorldTime::from_std_days(t1).expect("a day value is finite"),
            to: WorldTime::from_std_days(t2).expect("a day value is finite"),
            params: SUSTENANCE,
            // No sky in a planted-terrain fixture: the action clock takes its
            // base rate (spec §4.1).
            day_ticks: None,
            terrain: &terrain,
            folds: &folds,
        };
        let after2 = hornvale_kernel::tick(&after1, &[&sys2], &["drive-movements"], &reg).unwrap();
        let b_moves_2 = after2
            .find(AGENT_AT)
            .filter(|f| f.subject == b_entity && f.provenance != "test")
            .count();
        assert_eq!(
            b_moves_2,
            b_moves_1.len(),
            "once out of the halo B settles — the wave terminates (no perpetual stampede)"
        );

        // --- The control run: B alone (A absent). ---
        // With no primary-afraid neighbour the alarm field is EMPTY, so B feels
        // nothing borrowed and never flees. (It may amble home, but never on a
        // flight errand — the flight was borrowed, not intrinsic.)
        let mut control = Ledger::default();
        let cb = build_b(&mut control);
        let cb_entity = cb.entity;
        let folds = test_folds();
        let csys = DriveMovements {
            npcs: vec![cb.clone()],
            from: WorldTime::from_std_days(t0).expect("a day value is finite"),
            to: WorldTime::from_std_days(t1).expect("a day value is finite"),
            params: SUSTENANCE,
            // No sky in a planted-terrain fixture: the action clock takes its
            // base rate (spec §4.1).
            day_ticks: None,
            terrain: &terrain,
            folds: &folds,
        };
        let cafter = hornvale_kernel::tick(&control, &[&csys], &["drive-movements"], &reg).unwrap();
        // THE NEGATIVE CONTROL, and the reason the re-point above is not
        // cosmetic: a control that reads zero because its predicate can never
        // match is indistinguishable from one that reads zero because the
        // behaviour is absent. `b_fear_moves >= 1` above is this control's
        // positive twin on the same instrument, which is what keeps this
        // zero meaningful.
        let c_fear = cafter
            .find(ERRAND_FLIGHT)
            .filter(|f| f.subject == cb_entity)
            .count();
        assert_eq!(
            c_fear, 0,
            "with no distressed neighbour present, B never flees — the flight was borrowed"
        );
    }

    #[test]
    fn the_threat_niche_is_derived_from_nature() {
        // THE BANE: HEAT/COLD derive from the temperature optimum, UNCANNY from
        // the thermal strategy.
        let cold_adapted = ConditionResponse {
            optimum: -10.0,
            width: 20.0,
            devotion: 0.5,
        };
        let warm_adapted = ConditionResponse {
            optimum: 25.0,
            width: 20.0,
            devotion: 0.5,
        };
        let cold = derive_threat_niche(
            &cold_adapted,
            ThermalStrategy::Endothermic,
            &default_diet_niche(),
        );
        let warm = derive_threat_niche(
            &warm_adapted,
            ThermalStrategy::Endothermic,
            &default_diet_niche(),
        );
        // A cold-adapted creature dreads HEAT more than a warm one; the reverse
        // for COLD.
        assert!(cold.heat > warm.heat, "the cold-adapted fear heat more");
        assert!(warm.cold > cold.cold, "the warm-adapted fear cold more");
        // A mortal fears the uncanny; an ametabolic elemental does not.
        assert_eq!(cold.uncanny, 1.0, "a mortal fears the eldritch");
        let elemental = derive_threat_niche(
            &cold_adapted,
            ThermalStrategy::Absent,
            &default_diet_niche(),
        );
        assert_eq!(elemental.uncanny, 0.0, "an elemental IS the eldritch");
    }

    #[test]
    fn two_species_read_the_same_hot_cell_differently() {
        // THE BANE, per-kind fear: a HOT room dreaded by a cold-adapted creature,
        // shrugged off by a heat-adapted one — the niche·hazard dot.
        let room = raddr(1.0);
        let t = PlantedTerrain::hazards_map([(
            room.clone(),
            Hazards {
                uncanny: 0.0,
                heat: 0.8,
                cold: 0.0,
                predator: 0.0,
            },
        )]);
        let v = view_at(room.clone());
        let cold_adapted = derive_threat_niche(
            &ConditionResponse {
                optimum: -10.0,
                width: 20.0,
                devotion: 0.5,
            },
            ThermalStrategy::Endothermic,
            &default_diet_niche(),
        );
        let warm_adapted = derive_threat_niche(
            &ConditionResponse {
                optimum: 45.0,
                width: 20.0,
                devotion: 0.5,
            },
            ThermalStrategy::Endothermic,
            &default_diet_niche(),
        );
        let fears = Danger {
            terrain: &t,
            threat_niche: cold_adapted,
            boldness: BOLDNESS_STEADY,
            alarm: None,
            dread: None,
        };
        let shrugs = Danger {
            terrain: &t,
            threat_niche: warm_adapted,
            boldness: BOLDNESS_STEADY,
            alarm: None,
            dread: None,
        };
        assert!(
            fears.urgency(&v) > shrugs.urgency(&v),
            "the cold-adapted creature dreads the heat the warm one shrugs off: \
             {} vs {}",
            fears.urgency(&v),
            shrugs.urgency(&v)
        );
        // A creature fearless of a hazard (weight 0) feels nothing there.
        assert_eq!(
            shrugs.urgency(&v),
            0.0,
            "a fully heat-adapted creature (heat weight 0) feels no heat-dread"
        );
    }

    #[test]
    fn the_predator_weight_derives_from_carnivory() {
        // THE QUARRY (the eater-eaten link): a herbivore fears predators, an
        // obligate apex does not — `(1 − carnivory) × latent scale`.
        let temp = DEFAULT_TEMPERATURE_NICHE;
        let herbivore = ResourceVector::new(&[(PLANT_FORAGE, 1.0)]).unwrap();
        let omnivore = ResourceVector::new(&[(PLANT_FORAGE, 0.5), (ANIMAL_PREY, 0.5)]).unwrap();
        let apex = ResourceVector::new(&[(ANIMAL_PREY, 1.0)]).unwrap();
        let w = |diet: &ResourceVector| {
            derive_threat_niche(&temp, ThermalStrategy::Endothermic, diet).predator
        };
        assert!(
            (w(&herbivore) - PREDATOR_LATENT_SCALE).abs() < 1e-9,
            "a herbivore fears predators"
        );
        assert!(w(&omnivore) < w(&herbivore), "an omnivore fears them less");
        assert_eq!(
            w(&apex),
            0.0,
            "an obligate apex does not fear predators — it IS one"
        );
    }

    #[test]
    fn a_vulnerable_creature_dreads_predator_ground_an_apex_does_not() {
        // THE QUARRY, per-kind biotic fear: a HIGH-predator room dreaded by a
        // (vulnerable, coward-to-amplify-the-latent) herbivore, ignored by an apex.
        let room = raddr(1.0);
        let t = PlantedTerrain::hazards_map([(
            room.clone(),
            Hazards {
                uncanny: 0.0,
                heat: 0.0,
                cold: 0.0,
                predator: 1.0,
            },
        )]);
        let v = view_at(room);
        let temp = DEFAULT_TEMPERATURE_NICHE;
        let herbivore = derive_threat_niche(
            &temp,
            ThermalStrategy::Endothermic,
            &ResourceVector::new(&[(PLANT_FORAGE, 1.0)]).unwrap(),
        );
        let apex = derive_threat_niche(
            &temp,
            ThermalStrategy::Endothermic,
            &ResourceVector::new(&[(ANIMAL_PREY, 1.0)]).unwrap(),
        );
        // A coward (boldness 0 → ×2) to lift the latent-scaled dread above act.
        let quarry = Danger {
            terrain: &t,
            threat_niche: herbivore,
            boldness: 0.0,
            alarm: None,
            dread: None,
        };
        let hunter = Danger {
            terrain: &t,
            threat_niche: apex,
            boldness: 0.0,
            alarm: None,
            dread: None,
        };
        assert!(
            quarry.urgency(&v) > 0.0,
            "the herbivore dreads predator ground: {}",
            quarry.urgency(&v)
        );
        assert_eq!(
            hunter.urgency(&v),
            0.0,
            "the apex feels no dread of predators — it is one"
        );
    }

    #[test]
    fn loneliness_is_zero_at_home_rises_with_distance_and_lapses_when_unreachable() {
        // The three regimes of the social pull (The Belonging). Takes the hop
        // count directly (the-waymark, Task 4: `loneliness_from_distance` is
        // `loneliness_from_plan`'s successor, reading a `HomeNavFeature`'s
        // `distance` rather than a full plan — see its own doc).
        assert_eq!(
            loneliness_from_distance(Some(0)),
            0.0,
            "at home (zero hops) → not lonely"
        );
        assert_eq!(
            loneliness_from_distance(Some(10)),
            10.0 / LONELY_SCALE_HOPS,
            "loneliness rises with the hop-distance home"
        );
        assert_eq!(
            loneliness_from_distance(None),
            0.0,
            "home beyond reach → DORMANT (0), not distress — social is comfort, \
             an unreachable home is a relocation"
        );
    }

    #[test]
    fn social_proposal_and_serviceability_are_the_home_step() {
        let home = raddr(1.0);
        let step = home.neighbors()[0].clone();
        let social = Social {
            loneliness: 0.9,
            home_step: Some(Action::MoveTo(step.clone())),
        };
        let view = view_at(home.neighbors()[1].clone());
        assert_eq!(
            social.proposal(&view, PLAN_BUDGET),
            Some(Action::MoveTo(step.clone())),
            "the proposal is the precomputed step home"
        );
        assert_eq!(
            social.serviceability(&Action::MoveTo(step), &view, PLAN_BUDGET, &mut || None),
            1.0,
            "the home-step is served"
        );
        assert_eq!(
            social.serviceability(&Action::Drink, &view, PLAN_BUDGET, &mut || None),
            0.0,
            "nothing else eases loneliness"
        );
    }

    #[test]
    fn a_lonely_creature_yields_to_thirst_but_homes_when_sated() {
        // COMFORT-tier: a thirsty AND lonely creature attends thirst first
        // (survival > comfort); sated, it heads home.
        let home = raddr(1.0);
        let pos = home.neighbors()[2].clone(); // one hop from home
        let water = home.neighbors()[1].clone();
        // The real home-step from `pos` (a genuine neighbour of `pos`).
        let plan = plan_to_room(&pos, &home, PLAN_BUDGET, &std::collections::BTreeSet::new());
        let step = plan.clone().and_then(|p| p.into_iter().next()).unwrap();
        let social = Social {
            loneliness: 0.9,
            home_step: Some(step.clone()),
        };
        let thirst = Thirst { params: SUSTENANCE };
        let drives: [&dyn Drive; 2] = [&thirst, &social];
        // Thirsty (drive past act) and knows nearby water: thirst wins.
        let thirsty = Perceived {
            position: pos.clone(),
            drive: 0.95,
            fatigue: 0.0,
            believed_water: Some(water.clone()),
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: None,
        };
        let r = arb(
            &thirsty,
            &home,
            &drives,
            1.0,
            0.0,
            false,
            true,
            Mode::Idle,
            PLAN_BUDGET,
        );
        assert_eq!(
            r.affect.object,
            Some(DriveKind::Thirst),
            "survival thirst outranks comfort loneliness: {:?}",
            r.affect
        );
        // Sated (thirst below act): only social active → heads home.
        let sated = Perceived {
            position: pos.clone(),
            drive: 0.0,
            fatigue: 0.0,
            believed_water: None,
            believed_hazard: std::collections::BTreeSet::new(),
            explore_step: None,
        };
        let r2 = arb(
            &sated,
            &home,
            &drives,
            1.0,
            0.0,
            false,
            true,
            Mode::Idle,
            PLAN_BUDGET,
        );
        assert_eq!(
            r2.intent,
            Intent::Do(step),
            "sated, the lonely creature heads home: {:?}",
            r2.affect
        );
        assert_eq!(r2.affect.object, Some(DriveKind::Social));
    }

    #[test]
    fn an_ametabolic_creature_is_never_lonely() {
        // THE METABOLISM GATE, social edge (The Belonging): an ametabolic
        // creature carries no social drive — placed far from home it still reads
        // Content, where a metabolizer would head home.
        let home = raddr(1.0);
        let away = raddr(-1.0); // far side of the world (home reachable within budget)
        let terrain = PlantedTerrain::fresh_only(std::iter::empty());
        let mut ledger = Ledger::default();
        let e = ledger.mint_entity(test_lineage(ledger.entity_count() as u16));
        let reg = {
            let mut r = agent_at_reg();
            r.register_predicate(DRANK, false, "drank").unwrap();
            r.register_predicate(RESTED, false, "rested").unwrap();
            r.register_predicate(SLEPT, false, "slept").unwrap();
            r
        };
        commit_agent_at(&mut ledger, &reg, e, &away, 0.0);
        let base = Body {
            entity: e,
            village: None,
            perception: hornvale_species::PerceptionVector::MANIKIN,
            home: home.clone(),
            resource: home.clone(),
            species: "xorn".to_string(),
            activity: hornvale_species::ActivityCycle::Diurnal,
            temperature_niche: test_niche(),
            deliberation_latency: 0.5,
            time_horizon: 0.0,
            thermal_strategy: ThermalStrategy::Absent,
            niche: default_diet_niche(),
            boldness: 0.5,
            threat_niche: mortal_threat_niche(),
            // The action clock's reference mass (The Action Clock T2): tempo is
            // exactly `1.0` here, so this fixture's timings are unmoved.
            mass_kg: crate::clock::REFERENCE_MASS_KG,
            label: "xorn".to_string(),
        };
        let a = affect_of(
            &ledger,
            &test_folds(),
            &base,
            &[],
            WorldTime::from_std_days(0.5).expect("a day value is finite"),
            &terrain,
        );
        assert_eq!(
            a.label,
            AffectLabel::Content,
            "a construct far from home is not lonely: {a:?}"
        );
    }

    #[test]
    fn is_water_delegates_to_terrain_is_fresh_water() {
        // `raddr(seed)` feeds `Facet::containing([seed, 0.0, 0.0], 6)`, which
        // normalizes its input direction first — so `raddr(1.0)` and `raddr(2.0)`
        // collapse to the SAME room (both are the direction [1,0,0]). Use a
        // genuine mesh neighbor for `high` instead, so the two planted rooms
        // are actually distinct (deviation from the brief's literal `raddr(2.0)`;
        // see task-1-report.md). Renamed from
        // `is_water_is_the_elevation_threshold` (T5 re-wire): `is_water` no
        // longer reads elevation at all — it delegates to
        // `Terrain::is_fresh_water` (The Freshet's salt/fresh classification).
        let low = raddr(1.0);
        let high = low.neighbors()[0].clone();
        let t = PlantedTerrain::fresh_only([low.clone()]);
        assert!(is_water(&low, &t));
        assert!(!is_water(&high, &t));
    }

    #[test]
    fn downhill_step_picks_the_lowest_neighbor_deterministically() {
        let home = raddr(1.0);
        let ns = home.neighbors();
        // Make ns[1] strictly lowest; others high.
        let mut m = std::collections::BTreeMap::new();
        for (i, n) in ns.iter().enumerate() {
            m.insert(n.clone(), if i == 1 { 0.0 } else { 100.0 });
        }
        let t = PlantedTerrain::dry(m);
        assert_eq!(downhill_step(&home, &t), ns[1]);
    }

    #[test]
    fn nearest_water_finds_the_closest_water_room_by_hops() {
        // home (dry) -> a neighbor that is fresh water: 1 hop.
        let home = raddr(1.0);
        let near = home.neighbors()[0].clone();
        let t = PlantedTerrain::fresh_only([near.clone()]);
        assert_eq!(nearest_water(&home, &t, 10_000), Some(near));
    }

